def parse_geometry(text: str) -> tuple[int, int, int, int] | None:
    """Split a Tk geometry string into ``(w, h, x, y)`` (or ``None``).

    Only the full ``WxH+X+Y`` form is accepted -- a bare size or a bare
    position is not enough to restore a window deterministically.
    """
    match = re.match(r"^(\d+)x(\d+)([+-]\d+)([+-]\d+)$", str(text).strip())
    if match is None:
        return None
    return int(match.group(1)), int(match.group(2)), int(match.group(3)), int(match.group(4))


def dump_session(
    *,
    theme: str,
    geometry: str,
    tab: int,
    variables: dict[str, Any],
    families: dict[str, bool],
    texts: dict[str, str],
    paths: dict[str, str] | None = None,
    paths_multi: dict[str, list[str]] | None = None,
) -> dict[str, Any]:
    """Assemble the JSON-serialisable session payload (pure normaliser).

    Values are coerced to their session types here so the file can never
    carry a half-typed payload, whatever the caller collected.
    (100x-142) ``paths`` carries the picked file/folder PATHS (str keys,
    absolute paths as strings) -- the docking/util pickers a restart
    used to forget.  Older payloads without the key stay loadable.
    (100x-144) ``paths_multi`` carries the MULTI-file picks (str keys,
    lists of absolute path strings) -- the three Utilities pickers that
    hold whole lists; always present, so a payload without them
    round-trips identically.
    """
    payload = {
        "format": SESSION_FORMAT,
        "theme": theme if theme in _THEMES else "light",
        "geometry": str(geometry),
        "tab": int(tab),
        "variables": {str(name): value for name, value in variables.items()},
        "families": {str(name): bool(checked) for name, checked in families.items()},
        "texts": {str(name): str(content) for name, content in texts.items()},
        # always present (100x-142): a payload without picked paths
        # round-trips identically -- an empty dict, never a missing key
        "paths": {str(name): str(path) for name, path in (paths or {}).items()},
        # always present (100x-144): same discipline for the list picks
        # -- only list-valued entries ride, only their str members (a
        # stray non-list value drops its entry instead of being
        # char-split into single-character "paths")
        "paths_multi": {
            str(name): [str(path) for path in files if isinstance(path, str)]
            for name, files in (paths_multi or {}).items()
            if isinstance(files, list)
        },
    }
    return payload


def load_session(raw: Any) -> dict[str, Any] | None:
    """Validate a parsed session file into a trusted dict (or ``None``).

    Malformed files are rejected wholesale (``None``); structurally fine
    files get every field sanitised back to its session type, so the
    restore path never has to defend itself twice.
    """
    if not isinstance(raw, dict) or raw.get("format") != SESSION_FORMAT:
        return None
    theme = raw.get("theme")
    if theme not in _THEMES:
        theme = "light"
    geometry = raw.get("geometry")
    geometry = geometry if isinstance(geometry, str) else ""
    tab = raw.get("tab")
    if isinstance(tab, bool) or not isinstance(tab, int) or tab < 0:
        tab = 0
    variables = raw.get("variables")
    if not isinstance(variables, dict):
        variables = {}
    variables = {str(name): value for name, value in variables.items()}
    families = raw.get("families")
    if not isinstance(families, dict):
        families = {}
    families = {
        str(name): checked for name, checked in families.items() if isinstance(checked, bool)
    }
    texts = raw.get("texts")
    if not isinstance(texts, dict):
        texts = {}
    texts = {str(name): content for name, content in texts.items() if isinstance(content, str)}
    # (100x-142) the picked paths -- optional so older session files
    # (and every hand-built payload in the tests) stay loadable.
    paths = raw.get("paths")
    if not isinstance(paths, dict):
        paths = {}
    paths = {str(name): str(path) for name, path in paths.items() if isinstance(path, str)}
    # (100x-144) the multi-file picks -- same optionality, same
    # wholesale coercion: an entry survives only when its value is a
    # list, and only its string members ride (a foreign file degrades
    # to shorter honest lists, never a half-typed payload)
    paths_multi = raw.get("paths_multi")
    if not isinstance(paths_multi, dict):
        paths_multi = {}
    paths_multi = {
        str(name): [str(path) for path in files if isinstance(path, str)]
        for name, files in paths_multi.items()
        if isinstance(files, list)
    }
    return {
        "format": SESSION_FORMAT,
        "theme": theme,
        "geometry": geometry,
        "tab": tab,
        "variables": variables,
        "families": families,
        "texts": texts,
        "paths": paths,
        "paths_multi": paths_multi,
    }


def export_session(payload: dict[str, Any], path: str | Path) -> bool:
    """Write a session payload to ``path`` as shareable JSON.

    The file uses the exact same format as the auto-saved session
    (``format`` marker included), so an exported session can be mailed
    to a colleague and imported on their machine.  ``False`` on any
    write failure (unwritable directory, non-serialisable payload) --
    never an exception.
    """
    try:
        with open(path, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, indent=2)
        return True
    except (OSError, TypeError, ValueError):
        return False


def read_json_file(path: str | Path) -> Any | None:
    """Read parsed JSON from ``path`` (``None`` on any failure)."""
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)
    except (OSError, ValueError):
        return None


#: (100x-137) The standalone report-order artifact's format marker and
#: kind tag -- a remembered page order shared WITHOUT the session's
#: inputs (the session file already carries the ``report_page_order``
#: key, but a whole session is more than a colleague needs when all
#: they asked for is the page order).
REPORT_ORDER_FORMAT = 1
REPORT_ORDER_KIND = "pharmaml-report-order"


def dump_report_order(order: dict[str, Any]) -> dict[str, Any]:
    """Assemble the shareable report-order payload (pure normaliser).

    Only the two real kinds survive, each label coerced to ``str``, so
    the file can never carry a half-typed payload whatever the caller
    held.  An empty memory dumps as an honest empty order -- importing
    it is a valid reset-to-walk-order, not an error.
    """
    clean: dict[str, list[str]] = {}
    for kind in ("table", "figure"):
        labels = order.get(kind) if isinstance(order, dict) else None
        if isinstance(labels, list):
            clean[kind] = [str(label) for label in labels]
    return {
        "format": REPORT_ORDER_FORMAT,
        "kind": REPORT_ORDER_KIND,
        "order": clean,
    }


def load_report_order(raw: Any) -> dict[str, list[str]] | None:
    """Validate a parsed order file into a trusted dict (or ``None``).

    A file without BOTH the format marker and the kind tag is foreign
    (rejected wholesale); a structurally fine file gets only the two
    real kinds back, each a list of ``str`` -- the restore path never
    has to defend itself twice.  A valid file whose order block is
    empty returns ``{}`` (the honest empty import, see the dump).
    """
    if (
        not isinstance(raw, dict)
        or raw.get("format") != REPORT_ORDER_FORMAT
        or raw.get("kind") != REPORT_ORDER_KIND
    ):
        return None
    stored = raw.get("order")
    if not isinstance(stored, dict):
        return None
    order: dict[str, list[str]] = {}
    for kind in ("table", "figure"):
        labels = stored.get(kind)
        if isinstance(labels, list) and all(
            isinstance(label, str) for label in labels
        ):
            order[kind] = list(labels)
    return order


