    def _build_menu(self) -> None:
        bar = tk.Menu(self)
        file_menu = tk.Menu(bar, tearoff=0)
        file_menu.add_command(label="Open CSV…", accelerator="Ctrl+O", command=self._menu_open_csv)
        file_menu.add_command(
            label="Save last figure…", accelerator="Ctrl+S", command=self._menu_save_figure
        )
        file_menu.add_command(
            label="Save session report (PDF)…", command=self._menu_save_session_report
        )
        # (100x-124) the portable twin -- pharmaml.viz.HTMLReport's first
        # caller anywhere: same two axes, metric cards, no fpdf needed.
        file_menu.add_command(
            label="Save session report (HTML)…", command=self._menu_save_session_report_html
        )
        file_menu.add_separator()
        file_menu.add_command(
            label="Save session now", accelerator="Ctrl+Shift+S", command=self._save_session_now
        )
        file_menu.add_command(label="Clear saved session…", command=self._clear_saved_session)
        # (100x-136) the order memory's always-available forget -- the
        # dialog's Reset only exists while the picklist is open (and only
        # works while a drift exists); this one forgets from anywhere.
        file_menu.add_command(
            label="Clear remembered report order…", command=self._clear_report_order
        )
        # (100x-137) the order memory's SHARE pair -- the standalone
        # artifact (just the preference, none of the session's inputs):
        # export writes the tiny order file, import adopts one and
        # writes the session through immediately.
        file_menu.add_command(
            label="Export remembered order…", command=self._export_report_order
        )
        file_menu.add_command(
            label="Import remembered order…", command=self._import_report_order
        )
        file_menu.add_command(label="Export session…", command=self._export_session)
        file_menu.add_command(label="Import session…", command=self._import_session)
        file_menu.add_command(
            label="Reset current tab to defaults",
            accelerator="Ctrl+Shift+R",
            command=self._reset_current_tab,
        )
        file_menu.add_separator()
        file_menu.add_command(label="Exit", accelerator="Ctrl+Q", command=self._on_close)
        bar.add_cascade(label="File", menu=file_menu)

        view_menu = tk.Menu(bar, tearoff=0)
        # the card finder (100x-120): Ctrl+F, also bound below
        view_menu.add_command(
            label="Find a card…", accelerator="Ctrl+F", command=self._find_card_dialog
        )
        view_menu.add_separator()
        self._theme_var = tk.StringVar(value=self._theme)
        for label, value in (("Follow system", "auto"), ("Light", "light"), ("Dark", "dark")):
            view_menu.add_radiobutton(
                label=label, value=value, variable=self._theme_var, command=self._on_theme_change
            )
        # (100x-129) the radios pick more than the window's palette:
        # both session reports ride them (the HTML's initial data-theme
        # and the PDF's ink variant), so say so right under them -- a
        # disabled caption is the menu's own quiet affordance.
        view_menu.add_command(
            label="(both session reports save in this theme)",
            state="disabled",
        )
        # Shortcut-hint row visibility (100x-65): a plain tk.Variable, so
        # the generic session machinery persists it for free.
        self._hints_var = tk.BooleanVar(value=True)
        view_menu.add_checkbutton(
            label="Shortcut hints", variable=self._hints_var, command=self._apply_hint_visibility
        )
        # (100x-158) the DearPyGui affordance preferences: the interactive
        # figure toolbars (pan / zoom / save on every embedded figure --
        # dpg plots are interactive out of the box) and the UI font size
        # (dpg's global font scale, as a discrete 9-12 pt menu).  Both
        # ride plain tk.Variables, so the session machinery persists them
        # exactly like the hint row above.
        self._toolbars_var = tk.BooleanVar(value=True)
        view_menu.add_checkbutton(
            label="Figure toolbars",
            variable=self._toolbars_var,
            command=self._apply_toolbar_visibility,
        )
        view_menu.add_separator()
        self._font_var = tk.IntVar(value=10)
        font_menu = tk.Menu(view_menu, tearoff=0)
        for size in (9, 10, 11, 12):
            font_menu.add_radiobutton(
                label=f"{size} pt",
                value=size,
                variable=self._font_var,
                command=self._apply_font_size,
            )
        view_menu.add_cascade(label="Font size", menu=font_menu)
        self._menu_tints.append(font_menu)
        view_menu.add_separator()
        # (100x-159) DearPyGui's developer tools, translated honestly:
        # the metrics window's census + the tool inspector's palette.
        view_menu.add_command(
            label="GUI metrics\u2026",
            command=self._show_gui_metrics,
        )
        bar.add_cascade(label="View", menu=view_menu)

        help_menu = tk.Menu(bar, tearoff=0)
        help_menu.add_command(label="About PharmaML Playground", command=self._show_about)
        help_menu.add_command(label="Dependency report", command=self._show_dependency_report)
        bar.add_cascade(label="Help", menu=help_menu)
        self.configure(menu=bar)
        # (100x-159) the font cascade rides the tint list too -- the
        # round-41 build appended it ABOVE this reassignment, so the
        # font submenu silently lost its tint on every theme flip.
        self._menu_tints = [bar, file_menu, view_menu, font_menu, help_menu]
        self._tint_menus()
        self.bind_all("<Control-o>", lambda _e: self._menu_open_csv())
        self.bind_all("<Control-s>", lambda _e: self._menu_save_figure())
        self.bind_all("<Control-Shift-S>", lambda _e: self._save_session_now())
        # 100x-65: the menu (and the docstring) had advertised Ctrl+Shift+R
        # since 100x-54, but no binding ever existed -- pressing it did
        # nothing.  Bound now, and the test suite pins the whole set.
        self.bind_all("<Control-Shift-R>", lambda _e: self._reset_current_tab())
        # 100x-120: the card finder -- bound and advertised in the hint
        # row together with the rest of the accelerators.
        self.bind_all("<Control-f>", lambda _e: self._find_card_dialog())
        self.bind_all("<Control-q>", lambda _e: self._on_close())

    def _build_statusbar(self) -> None:
        bar = ttk.Frame(self, style="Status.TFrame", padding=(12, 5))
        bar.pack(side="bottom", fill="x")
        self._status_bar = bar  # pinned so tests can order hint row vs bar
        if self.pharmaml is not None:
            left = f"pharmaml {self.pharmaml.__version__} · toolkit v{__version__}"
        else:
            left = (
                "pharmaml not loaded -- run from the toolkit root or "
                f"pip install -e . · toolkit v{__version__}"
            )
        ttk.Label(bar, text=left, style="Status.TLabel").pack(side="left")
        self._job_label = ttk.Label(bar, text="idle", style="Status.TLabel")
        self._job_label.pack(side="right", padx=(12, 0))
        self._progress = ttk.Progressbar(bar, mode="indeterminate", length=130)
        self._progress.pack(side="right")

    def _build_hintbar(self) -> None:
        """The keyboard-shortcut hint row (100x-65), above the status bar.

        One quiet line listing every global accelerator, so the bindings
        are discoverable without opening a menu.  ``View \u25b8 Shortcut
        hints`` (or the row's own ``Hide`` button) toggles it; the
        preference is a plain ``tk.Variable`` on ``self``, so the session
        machinery saves and restores it like any other input.  Packed
        ``side="bottom"`` AFTER the status bar claimed the bottom edge,
        which pins it directly above the status line.
        """
        bar = ttk.Frame(self, style="Status.TFrame", padding=(12, 2))
        label = ttk.Label(bar, text=shortcut_hints_text(), style="Status.TLabel")
        label.pack(side="left")
        Tooltip(
            label,
            "The global keyboard shortcuts, also listed in the File "
            "menu.  View \u25b8 Shortcut hints re-enables this row "
            "after hiding it (the preference is saved with the "
            "session).",
        )
        hide = ttk.Button(bar, text="Hide", style="Ghost.TButton", command=self._hide_hints)
        hide.pack(side="right", padx=(12, 0))
        Tooltip(hide, "Hide the shortcut hint row (View \u25b8 Shortcut hints brings it back).")
        self._hint_bar = bar
        bar.pack(side="bottom", fill="x")
        self._apply_hint_visibility()

    def _apply_hint_visibility(self) -> None:
        """Show/hide the hint row to match :attr:`_hints_var`."""
        bar = getattr(self, "_hint_bar", None)
        if bar is None:
            return
        if self._hints_var.get():
            bar.pack(side="bottom", fill="x")
        else:
            bar.pack_forget()

    def _hide_hints(self) -> None:
        """The hint row's own Hide button -- flip the preference off."""
        self._hints_var.set(False)
        self._apply_hint_visibility()

    def _build_tabs(self) -> None:
        self._book = ttk.Notebook(self)
        self._book.pack(fill="both", expand=True, padx=10, pady=(10, 4))
        self._build_home_tab()
        self._build_chemistry_tab()
        self._build_pk_tab()
        self._build_cellline_tab()
        self._build_docking_tab()
        self._build_ml_tab()
        self._build_unsupervised_tab()
        self._build_dl_tab()
        self._build_generative_tab()
        self._build_utilities_tab()
        # keyboard tab cycling (100x-119): Ctrl+PgDn / Ctrl+PgUp walk the
        # notebook without reaching for the mouse
        self.bind("<Control-Next>", self._cycle_tab)
        self.bind("<Control-Prior>", self._cycle_tab)

    def _cycle_tab(self, event: Any) -> str:
        """Ctrl+PgDn / Ctrl+PgUp -- select the next / previous tab."""
        try:
            count = self._book.index("end")
            current = self._book.index(self._book.select())
        except tk.TclError:  # pragma: no cover - no tab selected yet
            return "break"
        step = 1 if str(event.keysym) == "Next" else -1
        self._book.select((current + step) % count)
        return "break"

    def _jump_to_tab(self, index: int) -> None:
        """Select a tab by index (the home tab's quick-jump chips)."""
        try:
            if 0 <= index < self._book.index("end"):
                self._book.select(index)
        except tk.TclError:  # pragma: no cover - no tab selected yet
            pass

    # -- the Ctrl+F card finder (100x-120) ----------------------------- #
    def _card_tab_index(self, shell: Any, pages: list[Any]) -> int | None:
        """Resolve which tab page a card shell descends from."""
        node: Any = shell
        while node is not None:
            for index, page in enumerate(pages):
                if node is page:
                    return index
            try:
                node = node.master
            except tk.TclError:  # a destroyed ancestor
                return None
        return None

    def _live_cards(self) -> list[tuple[str, str, Any, int]]:
        """The card index filtered to shells of THIS app's live tabs."""
        try:
            pages = [self._book.nametowidget(tab) for tab in self._book.tabs()]
        except tk.TclError:  # pragma: no cover - no notebook yet
            return []
        live: list[tuple[str, str, Any, int]] = []
        for title, subtitle, shell in _CARD_INDEX:
            try:
                if not bool(shell.winfo_exists()):
                    continue
            except tk.TclError:
                continue
            index = self._card_tab_index(shell, pages)
            if index is not None:
                live.append((title, subtitle, shell, index))
        return live

    def _finder_remember(self, tab_index: int, title: str) -> None:
        """Record a card jump for the finder's recency row (100x-130).

        Most-recent-first, de-duplicated, capped at
        ``_FINDER_RECENT_MAX`` entries -- the same honest memory the
        web twin's finder gained this round, persisted with the session
        (``finder_recent`` text key, JSON-encoded).  (100x-142) the key
        is ``"tab:title"`` -- five card titles are duplicated ACROSS
        tabs (Dataset, Preview, Results …), and the old title-only key
        landed the chip on whichever tab built first.  Legacy bare
        titles from an older session file are dropped on re-membering
        (they cannot name a tab).
        """
        key = f"{tab_index}:{title}"
        recent = [
            entry
            for entry in getattr(self, "_finder_recent", [])
            if entry != key and entry != title
        ]
        recent.insert(0, key)
        self._finder_recent = recent[:_FINDER_RECENT_MAX]

    def _find_card_dialog(self) -> None:
        """Ctrl+F -- a live card finder over every tab (100x-120).

        Typing filters the card index on title + subtitle; Enter (or a
        double-click) selects the card's tab, scrolls the card into
        view and flashes its border -- a 60-card window becomes
        navigable without hunting through tabs.

        (100x-130) A "Recently jumped" chip row rides under the query:
        one click returns to the cards you keep visiting, without
        retyping (the memory is de-duplicated, capped and persisted
        with the session -- restarting the app keeps it).

        (100x-131) The row carries its own "Clear" ghost button: one
        click forgets every remembered jump (the session-persisted
        ``finder_recent`` key too) and the row collapses in place --
        the honest empty, no re-open needed.  The web twin's finder
        row gained the same affordance (localStorage-backed).
        """
        if tk is None:  # pragma: no cover - headless import
            return
        win = tk.Toplevel(self)
        win.title("Find a card")
        win.configure(background=BG)
        win.transient(self)
        try:
            win.geometry(f"+{self.winfo_rootx() + 140}+{self.winfo_rooty() + 110}")
        except tk.TclError:  # pragma: no cover - unmapped parent
            pass
        ttk.Label(
            win,
            text="Type words from a card's title or subtitle — Enter jumps to it.",
            style="CardMuted.TLabel",
        ).pack(anchor="w", padx=14, pady=(12, 4))
        entry = ttk.Entry(win, width=54)
        # 100x-121: the finder remembers its last query -- prefilled here,
        # persisted with the session ("finder" text key).
        last_query = getattr(self, "_finder_last_query", "")
        if last_query:
            entry.insert(0, last_query)
        entry.pack(fill="x", padx=14, pady=(0, 8))

        def jump_title(remembered: str) -> None:
            """Chip shortcut: jump straight to a remembered card.

            (100x-142) The memory keys on "tab:title" -- five card
            titles are duplicated ACROSS tabs, so a title-only match
            jumped to whichever tab built first.  Bare titles from an
            older session keep the first-match fallback.
            """
            index: int | None = None
            title = remembered
            head, sep, rest = remembered.partition(":")
            if sep and head.isdigit():
                index = int(head)
                title = rest
            for card_title, _subtitle, _shell, card_index in self._live_cards():
                if card_title == title and (index is None or card_index == index):
                    self._jump_to_card(card_index, card_title)
                    win.destroy()
                    return

        # (100x-130) the recency row -- one chip per recently jumped
        # card, filtered to the cards that are live RIGHT NOW (a
        # remembered title whose shell vanished is honestly omitted,
        # never a dead button).  (100x-131) the row carries its own
        # "Clear" ghost button: one click empties the memory (the
        # session-persisted ``finder_recent`` key too) and the row
        # collapses in place -- the honest empty, no re-open needed.
        # (100x-142) entries are "tab:title" keys; a title duplicated
        # across tabs gets the tab label appended so the chips stay
        # honest about WHICH Dataset / Results card they open.
        live_cards = self._live_cards()
        live_keys = {(card_index, card_title) for card_title, _s, _sh, card_index in live_cards}
        title_counts: dict[str, int] = {}
        for card_title, _s, _sh, _i in live_cards:
            title_counts[card_title] = title_counts.get(card_title, 0) + 1

        def _parse_remembered(entry: str) -> tuple[int | None, str]:
            head, sep, rest = entry.partition(":")
            if sep and head.isdigit():
                return int(head), rest
            return None, entry

        remembered_cards: list[tuple[str, int | None, str]] = []
        for remembered_key in getattr(self, "_finder_recent", []):
            index, title = _parse_remembered(remembered_key)
            if index is not None:
                if (index, title) in live_keys:
                    remembered_cards.append((remembered_key, index, title))
            elif any(card_title == title for card_title, _s, _sh, _i in live_cards):
                remembered_cards.append((remembered_key, None, title))
        if remembered_cards:
            recent_row = ttk.Frame(win, style="Card.TFrame")
            recent_row.pack(fill="x", padx=14, pady=(0, 6))
            ttk.Label(
                recent_row, text="Recently jumped:", style="CardMuted.TLabel"
            ).pack(side="left")
            chips = ttk.Frame(recent_row, style="Card.TFrame")
            chips.pack(side="left", padx=(8, 0))
            for remembered_key, index, title in remembered_cards:
                chip_text = title
                if index is not None and title_counts.get(title, 0) > 1:
                    with contextlib.suppress(tk.TclError):
                        chip_text = f"{title} · {self._book.tab(index, 'text').strip()}"
                chip = ttk.Button(
                    chips,
                    text=_truncate_caption_text(chip_text, 24),
                    style="Ghost.TButton",
                    command=lambda remembered=remembered_key: jump_title(remembered),
                )
                chip.pack(side="left", padx=(4, 0))
                Tooltip(
                    chip,
                    f"Jump back to {title} -- one of your most recent "
                    "finder jumps (the row remembers up to "
                    f"{_FINDER_RECENT_MAX}, newest first).",
                )

            def clear_recent() -> None:
                """Forget every remembered jump (the row's Clear button)."""
                self._finder_recent = []
                recent_row.destroy()

            clear_button = ttk.Button(
                recent_row,
                text="Clear",
                style="Ghost.TButton",
                command=clear_recent,
            )
            clear_button.pack(side="right", padx=(8, 0))
            Tooltip(
                clear_button,
                "Forget every remembered jump -- the row disappears "
                "until you land on cards again (also clears the "
                "session-persisted memory).",
            )

        tree = ttk.Treeview(win, columns=("card", "tab"), show="headings", height=12)
        tree.heading("card", text="card")
        tree.heading("tab", text="tab")
        tree.column("card", width=360)
        tree.column("tab", width=130)
        # (100x-158) the finder's tree is created per-dialog, so the
        # post-build chrome walk cannot reach it -- attach here.
        attach_table_chrome(tree)
        tree.pack(fill="both", expand=True, padx=14, pady=(0, 4))
        ttk.Label(
            win, text="Enter jump · double-click jump · Esc close", style="CardMuted.TLabel"
        ).pack(anchor="w", padx=14, pady=(0, 10))

        def refresh() -> None:
            query = entry.get().strip().lower()
            self._finder_last_query = entry.get().strip()
            tree.delete(*tree.get_children())
            for title, subtitle, _shell, index in self._live_cards():
                haystack = f"{title} {subtitle}".lower()
                if query and not all(word in haystack for word in query.split()):
                    continue
                try:
                    tab_name = str(self._book.tab(index, "text")).strip()
                except tk.TclError:  # pragma: no cover - tab vanished
                    continue
                tree.insert("", "end", values=(title, tab_name), iid=f"{index}:{title}")

        def jump(item: str | None = None) -> None:
            picked = item or (tree.selection() or [None])[0]
            if not picked:
                return
            index = int(str(picked).split(":", 1)[0])
            title = str(picked).split(":", 1)[1]
            self._jump_to_card(index, title)
            win.destroy()

        entry.bind("<KeyRelease>", lambda _e: refresh())
        entry.bind("<Return>", lambda _e: jump())
        tree.bind("<Double-1>", lambda e: jump(tree.identify_row(e.y)))
        win.bind("<Escape>", lambda _e: win.destroy())
        refresh()
        entry.focus_set()

    def _jump_to_card(self, tab_index: int, title: str) -> None:
        """Select the tab, scroll the card into view and flash it.

        (100x-130) Every jump is remembered for the finder's recency
        row -- the desktop twin of the web finder's own memory, so the
        cards you keep visiting stay one click away.
        """
        self._jump_to_tab(tab_index)
        self._finder_remember(tab_index, title)
        self.update_idletasks()
        for entry_title, _subtitle, shell in _CARD_INDEX:
            if entry_title != title:
                continue
            try:
                if not bool(shell.winfo_exists()):
                    continue
            except tk.TclError:
                continue
            if (
                self._card_tab_index(
                    shell, [self._book.nametowidget(tab) for tab in self._book.tabs()]
                )
                != tab_index
            ):
                continue
            # (100x-159) a jump to a folded card unfolds it first --
            # scrolling to a hidden body would be a lie.
            for collapse_key, entry in _COLLAPSE_CARDS.items():
                if entry["shell"] is shell and not bool(entry.get("expanded", True)):
                    _set_card_expanded(collapse_key, True)
                    self.update_idletasks()
            page = self._book.nametowidget(self._book.tabs()[tab_index])
            canvas = getattr(page, "_canvas", None)
            if canvas is not None:
                body_height = int(page.body.winfo_reqheight() or 1)
                fraction = max(0.0, min(0.99, (shell.winfo_y() - 12) / max(1, body_height)))
                canvas.yview_moveto(fraction)
            shell.configure(highlightbackground=ACCENT, highlightthickness=3)
            self.after(1200, lambda s=shell: self._unflash_card(s))
            break

    def _unflash_card(self, shell: Any) -> None:
        """Restore a flashed card's border (the finder's highlight)."""
        with contextlib.suppress(tk.TclError):
            if bool(shell.winfo_exists()):
                shell.configure(highlightbackground=BORDER, highlightthickness=1)

    def _new_page(self, title: str, reset: bool = True) -> Any:
        page = ScrollFrame(self._book)
        grid = ttk.Frame(page.body, style="Tab.TFrame")
        grid.pack(fill="both", expand=True)
        grid.columnconfigure(0, weight=1, uniform="cards")
        grid.columnconfigure(1, weight=1, uniform="cards")
        page.grid = grid  # type: ignore[attr-defined]
        self._book.add(page, text=f"  {title}  ")
        if reset:
            # per-tab reset button (100x-55): the ownership map is keyed
            # by tab index, and add() just appended this page -- its index
            # is the last one.  Pinned in the non-scrolling footer so it
            # stays reachable without scrolling back up.
            index = len(self._book.tabs()) - 1
            button = ttk.Button(
                page.footer,
                text="Reset this tab to defaults",
                style="Ghost.TButton",
                command=lambda idx=index: self._reset_tab(idx),
            )
            button.pack(side="right", padx=(0, 14), pady=(4, 5))
            Tooltip(
                button,
                "Restore only THIS tab's inputs to their launch "
                "defaults -- every other tab keeps its live "
                "values (same as File \u25b8 Reset current tab).",
            )
            # per-tab copy button (100x-60): the same ownership map, read
            # LIVE -- a share-lite JSON snippet of this tab's inputs on
            # the clipboard (paste into an issue, a script, or a message).
            copy_button = ttk.Button(
                page.footer,
                text="Copy inputs as JSON",
                style="Ghost.TButton",
                command=lambda idx=index: self._copy_tab_inputs(idx),
            )
            copy_button.pack(side="right", padx=(0, 6), pady=(4, 5))
            Tooltip(
                copy_button,
                "Copy THIS tab's live inputs as a JSON snippet -- the "
                "same fields the session file stores, for one tab. "
                "Paste it into an issue report or a colleague's "
                "import (File \u25b8 Import session takes full files).",
            )
        return page

    def _action_button(
        self,
        parent: Any,
        text: str,
        command: Callable[[], None],
        tooltip: str = "",
        primary: bool = False,
    ) -> Any:
        button = ttk.Button(
            parent, text=text, command=command, style="Primary.TButton" if primary else "TButton"
        )
        if tooltip:
            Tooltip(button, tooltip)
        self._action_buttons.append(button)
        return button

    def _show_error(self, title: str, exc: BaseException) -> None:
        detail = f"{type(exc).__name__}: {exc}"
        print(detail, file=sys.stderr)
        messagebox.showerror(title, detail)

    def _require(self, module: str, feature: str) -> bool:
        """Gate a feature on a probed dependency with an install hint.

        (100x-142) The hint lookup used a bare ``next()`` -- a module
        name outside ``_DEPENDENCIES`` raised ``StopIteration`` INSIDE
        the Tk callback (surfacing as the generic "Unexpected error"
        dialog instead of an install hint).  The guarded fallback keeps
        the gate honest for any future dependency name.
        """
        if self.deps.get(module):
            return True
        pip_hint = next(
            (hint for name, _l, _p, hint in _DEPENDENCIES if name == module),
            f"{module}",
        )
        messagebox.showwarning(
            f"{feature} needs {module}",
            f"{feature} needs the {module} package, which is not installed.\n\n"
            f"    pip install {pip_hint}\n\n"
            "Install it, then restart the playground.",
        )
        return False

    def _require_pharmaml(self) -> bool:
        if self.pharmaml is not None:
            return True
        messagebox.showerror("pharmaml not loaded", _PHARMAML_HINT)
        return False

    def _start_job(
        self, label: str, work: Callable[..., Any], on_done: Callable[[Any], None] | None = None
    ) -> None:
        """Run ``work`` in a worker thread; render via ``on_done``.

        Progress (100x-106): a ``work`` that *accepts an argument*
        receives a reporter callable to push ``(done, total, note)``
        updates -- the status bar then switches from the marquee to a
        determinate bar carrying the fraction and a live "~ x left"
        ETA (see :meth:`_poll_progress`).  Zero-argument ``work``
        functions keep the historical indeterminate marquee.
        """
        if self._busy:
            messagebox.showinfo(
                "Busy",
                "Another calculation is still running -- please wait for it.",
            )
            return
        self._busy = True
        self._on_done = on_done
        for button in self._action_buttons:
            if button.winfo_exists():
                button.state(["disabled"])
        self._job_label_base = label
        self._job_started = time.monotonic()
        with contextlib.suppress(queue.Empty):
            while True:  # stale updates from a previous job never leak
                self._progress_updates.get_nowait()
        self._progress.start(12)
        self._job_label.configure(text=label)

        def runner() -> None:
            try:
                self._jobs.put((_call_work(work, self._report_progress), None))
            except BaseException as exc:  # noqa: BLE001 - surfaced in the UI
                self._jobs.put((None, exc))

        threading.Thread(target=runner, name="playground-job", daemon=True).start()

    def _report_progress(self, done: int, total: int | None = None, note: str = "") -> None:
        """Worker-thread progress feed (thread-safe: queue → poller).

        Called from inside ``work`` for every completed unit -- a tuner
        trial, a training epoch, a leaderboard model -- with the unit
        count, the total (``None`` for open-ended work) and an optional
        note rendered after the fraction.  Only the latest update is
        shown; the poller coalesces bursts.
        """
        self._progress_updates.put((int(done), total, note))

    def _poll_progress(self) -> None:
        """Drain progress updates into the status bar (bar + ETA).

        Coalesces everything queued into the newest update, then
        renders it: a determinate bar at ``done / total`` and a job
        label like ``tuning ann (regression) — 3/8 · ~45 s left · best
        0.712``.  The ETA extrapolates the elapsed/fraction ratio;
        total-less updates degrade to a plain counter.  Updates that
        arrive while no job is running (late stragglers) are dropped.
        """
        latest: tuple[int, int | None, str] | None = None
        with contextlib.suppress(queue.Empty):
            while True:
                latest = self._progress_updates.get_nowait()
        if latest is not None and self._busy:
            done, total, note = latest
            elapsed = max(time.monotonic() - self._job_started, 1e-9)
            text = self._job_label_base
            if total is not None and total > 0:
                fraction = min(done / total, 1.0)
                with contextlib.suppress(tk.TclError):
                    self._progress.stop()
                    self._progress.configure(mode="determinate", maximum=total)
                    self._progress["value"] = done
                text += f" — {done}/{total}"
                if fraction > 0.0:
                    remaining = elapsed * (1.0 - fraction) / fraction
                    text += f" · ~{_fmt_duration(remaining)} left"
            else:
                text += f" — {done}"
            if note:
                text += f" · {note}"
            with contextlib.suppress(tk.TclError):
                self._job_label.configure(text=text)
        # (100x-158) the DearPyGui affordance upkeep rides the same 150 ms
        # poll: prune destroyed figure toolbars, re-stripe any tree whose
        # row count changed (every populate path, unedited), all cheap.
        self._live_toolbars[:] = _toolbar_prune(self._live_toolbars)
        sweep_table_chrome()
        self.after(150, self._poll_progress)

    def _poll_jobs(self) -> None:
        try:
            result, error = self._jobs.get_nowait()
        except queue.Empty:
            self.after(80, self._poll_jobs)
            return
        self._busy = False
        self._progress.stop()
        with contextlib.suppress(tk.TclError):
            # back to the launch-time marquee for the next job: the
            # determinate mode a progress-reporting job switched to is
            # per-job state, never a permanent UI change.
            self._progress.configure(mode="indeterminate")
            self._progress["value"] = 0
        with contextlib.suppress(queue.Empty):
            while True:  # late progress stragglers never leak either
                self._progress_updates.get_nowait()
        # the 100x-119 UI pass: a finished job reports what it was and
        # how long it took (the label reverts to "idle" only when the
        # next job starts)
        elapsed = time.monotonic() - self._job_started
        label = getattr(self, "_job_label_base", "") or "job"
        if error is not None:
            self._job_label.configure(text=f"{label} FAILED after {_fmt_duration(elapsed)}")
        else:
            self._job_label.configure(text=f"{label} — done in {_fmt_duration(elapsed)}")
        for button in self._action_buttons:
            if button.winfo_exists():
                button.state(["!disabled"])
        if error is not None:
            traceback.print_exception(type(error), error, error.__traceback__)
            messagebox.showerror("Calculation failed", f"{type(error).__name__}: {error}")
        else:
            # (100x-142) capture-and-clear BEFORE invoking: a render
            # callback that chains straight into _start_job (e.g. an
            # auto-follow-up job) used to have its own on_done wiped
            # by the assignment below -- the chained result was then
            # silently discarded.  No current handler chains, but the
            # ordering was one refactor away from silent data loss.
            callback = self._on_done
            self._on_done = None
            if callback is not None:
                try:
                    callback(result)
                except Exception as exc:  # noqa: BLE001 - render errors are ours
                    self._show_error("Could not display the result", exc)
        # (100x-144) the chained-job guard: a render callback that
        # called _start_job re-set _on_done for its follow-up job --
        # wiping it here would discard that job's result silently.
        # Only an idle app still holds a stale callback worth clearing.
        if not self._busy:
            self._on_done = None
        self.after(80, self._poll_jobs)

    def report_callback_exception(self, exc: Any, val: Any, tb: Any) -> None:
        """Route Tk callback crashes to the console and a dialog."""
        traceback.print_exception(exc, val, tb)
        messagebox.showerror("Unexpected error", f"{type(val).__name__}: {val}")

    def _copy(self, text: str) -> None:
        self.clipboard_clear()
        self.clipboard_append(text)
        if self._busy:
            # (100x-142) a copy during a running job must not clobber
            # the live job label (the status bar IS the job's progress
            # line); the clipboard write -- the user's real intent --
            # still happens.
            return
        self._job_label.configure(text="copied to clipboard")
        self.after(1400, lambda: self._job_label.configure(text="idle"))

    def _close_embedded(self, host: Any) -> None:
        figure = getattr(host, "_pg_figure", None)
        if figure is None:
            return
        with contextlib.suppress(Exception):
            from pharmaml.viz import close_figure

            close_figure(figure)
        host._pg_figure = None

    def _figure_canvas_class(self) -> Any:
        """Return ``FigureCanvasTkAgg`` once, or None when it cannot load."""
        global _FIGURE_CANVAS, _FIGURE_CANVAS_PROBED
        if not _FIGURE_CANVAS_PROBED:
            _FIGURE_CANVAS_PROBED = True
            try:
                from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg

                _FIGURE_CANVAS = FigureCanvasTkAgg
            except ImportError:
                print(
                    "note: the TkAgg acceleration could not load on this Python "
                    "build -- figures render as PNG instead (fully functional)."
                )
                _FIGURE_CANVAS = None
        return _FIGURE_CANVAS

    def _render_figure(self, host: Any, figure: Any, caption: str | None = None) -> None:
        """Embed a matplotlib figure into ``host`` (replacing any prior one).

        Prefers the live TkAgg canvas; when the TkAgg acceleration cannot
        load (some Tcl 9 builds), falls back to rendering the figure with
        the Agg backend and displaying the PNG directly -- same figures,
        every machine.  (100x-122) every render also feeds the session
        figure registry the File ▸ Save session report walks.  (100x-133)
        ``caption`` overrides the running job's label in that registry --
        a card that can say something richer than its job name (the
        surgery grids' counts) passes it so the picklist's rows say what
        the page actually holds.
        """
        self._register_session_figure(host, figure, caption)
        self._close_embedded(host)
        for child in host.winfo_children():
            child.destroy()
        canvas_cls = self._figure_canvas_class()
        if canvas_cls is not None:
            canvas = canvas_cls(figure, master=host)
            # (100x-158) the DearPyGui interactive-plot parity: the
            # navigation toolbar (pan / zoom / save + coordinate readout)
            # and the dashed crosshair guides under the cursor.  Both
            # degrade silently on exotic Tk builds.
            self._attach_figure_toolbar(host, canvas)
            canvas.draw()
            widget = canvas.get_tk_widget()
            widget.configure(background=CARD, highlightthickness=0)
            widget.pack(fill="both", expand=True)
            self._attach_crosshair(canvas)
            self._figure_seq += 1
            host._pg_figure_seq = self._figure_seq
            host._pg_figure = figure
            self._last_figure = figure
            return
        import io

        buffer = io.BytesIO()
        figure.savefig(buffer, format="png", dpi=110, facecolor=CARD)
        data = buffer.getvalue()
        photo = tk.PhotoImage(data=data)
        # (100x-123) the PNG fallback cannot REDRAW like the TkAgg canvas
        # does, so an oversize raster used to show only its middle band
        # (the round-123 surgery grids were 385-682 px tall in 260 px
        # hosts -- the VLM screenshot review caught the clipping).  Fit
        # the whole figure instead: resample to the host's real box with
        # PIL (aspect kept, LANCZOS); without PIL the old behaviour
        # stands (matplotlib always depends on Pillow, so in practice
        # the resample always runs).
        try:
            from PIL import Image

            host.update_idletasks()
            box_w = max(int(host.winfo_width()), 100)
            box_h = max(int(host.winfo_height()), 100)
            with Image.open(io.BytesIO(data)) as raster:
                if raster.width > box_w or raster.height > box_h:
                    scale = min(box_w / raster.width, box_h / raster.height)
                    resample = getattr(Image, "Resampling", Image).LANCZOS
                    resized = raster.resize(
                        (
                            max(1, int(raster.width * scale)),
                            max(1, int(raster.height * scale)),
                        ),
                        resample,
                    )
                    out = io.BytesIO()
                    resized.save(out, format="PNG")
                    photo = tk.PhotoImage(data=out.getvalue())
        except Exception:  # noqa: BLE001 - keep the unscaled raster
            photo = tk.PhotoImage(data=data)
        label = tk.Label(host, image=photo, background=CARD)
        label.pack(fill="both", expand=True)
        label._pg_photo = photo  # keep a reference -- Tk frees unreferenced images
        self._figure_seq += 1
        host._pg_figure_seq = self._figure_seq
        host._pg_figure = figure
        self._last_figure = figure

    def _figure_host(self, parent: Any, height: int = 330) -> Any:
        """A reserved white area (grid-managed) that figures embed into."""
        host = tk.Frame(parent, background=CARD, height=height)
        grid_append(parent, host, sticky="nsew", pady=(6, 0), weight=True)
        host.pack_propagate(False)
        return host

    def _register_session_figure(
        self, host: Any, figure: Any, caption: str | None = None
    ) -> None:
        """Track one live ``(title, figure)`` per host for the session report.

        Called from :meth:`_render_figure` BEFORE the prior figure is
        closed: an existing host entry is replaced in place (order kept --
        the report reads top-of-session first), a new host appends.  The
        title defaults to the running job's label, the honest provenance
        of what drew the figure.  (100x-133) ``caption`` overrides that
        label -- the generative structure grids pass their counts ("Ring
        topology moves — 6 mutant(s)") so the pre-save picklist's rows
        and the report's figure captions carry the page's actual census,
        not just the card's job name.
        """
        title = caption or self._job_label_base or "figure"
        for entry in self._session_figures:
            if entry[0] is host:
                entry[1] = title
                entry[2] = figure
                return
        self._session_figures.append([host, title, figure])

    def _live_session_figures(self) -> list[list]:
        """Registry entries whose host AND figure are both still alive."""
        live: list[list] = []
        for entry in self._session_figures:
            host, _title, figure = entry
            if not host.winfo_exists():
                continue  # the card's tab was rebuilt (defensive)
            if getattr(host, "_pg_figure", None) is not figure:
                continue  # superseded inside the host (defensive)
            live.append(entry)
        return live

    def _card_title_for_widget(self, widget: Any) -> str | None:
        """The card title of the nearest registered shell above ``widget``.

        (100x-123) Walks the parent chain until a :data:`_CARD_INDEX`
        shell matches; widgets that live outside every card (the finder
        dialog's tree, the root itself) return ``None`` and are skipped
        by the table walk.
        """
        node = widget
        while node is not None:
            for title, _subtitle, shell in _CARD_INDEX:
                if shell is node:
                    return title
            node = getattr(node, "master", None)
        return None

    def _live_session_tables(self) -> list[tuple[str, list[str], list[list[str]]]]:
        """Every filled table on screen: ``(title, headings, rows)``.

        (100x-123) The report's table axis -- the figure registry's twin.
        Instead of registering at fill time (15+ scattered sites), the
        walk discovers every live :class:`ttk.Treeview` with rows and
        derives its provenance from the card index.  Trees outside any
        card (the finder dialog) are skipped; empty trees are skipped
        (an unfilled card has nothing to report).  Hierarchical trees
        (``show`` includes ``tree``) contribute their ``#0`` label as
        the first column, the same way the user reads them.
        """
        collected: list[tuple[str, list[str], list[list[str]]]] = []

        def visit(widget: Any) -> None:
            try:
                children = widget.winfo_children()
            except tk.TclError:
                return  # a destroyed intermediate (defensive)
            for child in children:
                if isinstance(child, ttk.Treeview):
                    rows = list(child.get_children())
                    if rows:
                        title = self._card_title_for_widget(child)
                        if title:
                            shows = [str(token) for token in child.cget("show")]
                            hierarchical = "tree" in shows
                            headings: list[str] = []
                            if hierarchical:
                                headings.append(str(child.heading("#0", "text") or "item"))
                            headings.extend(
                                str(child.heading(column, "text") or str(column))
                                for column in child["columns"]
                            )
                            data: list[list[str]] = []
                            for iid in rows:
                                values = [str(value) for value in child.item(iid, "values")]
                                if hierarchical:
                                    values.insert(0, str(child.item(iid, "text")))
                                data.append(values)
                            collected.append((title, headings, data))
                visit(child)

        visit(self)
        return collected

    # -- session + theme ------------------------------------------------- #
    def _read_session_file(self) -> Any:
        """Parse the session file, or ``None`` when absent/corrupt."""
        try:
            with session_path().open("r", encoding="utf-8") as handle:
                return json.load(handle)
        except FileNotFoundError:
            return None
        except (OSError, ValueError):
            return None

    def _resolve_auto_theme(self) -> str:
        """Map ``"auto"`` onto light/dark using the OS preference (Tk 8.6.13+).

        Anything the interpreter cannot answer (older Tk, Linux) falls
        back to light -- the palette the window was designed around.
        """
        with contextlib.suppress(Exception):
            if bool(self.tk.call("tk", "dark")):
                return "dark"
        return "light"

    def _on_theme_change(self) -> None:
        """View-menu callback: flip the palette across the live window."""
        choice = self._theme_var.get()
        self._theme = choice if choice in _THEMES else "light"
        self._set_theme(self._resolve_auto_theme() if self._theme == "auto" else self._theme)

    def _set_theme(self, resolved: str) -> None:
        """Apply a resolved palette and recolour every live widget."""
        previous = _PALETTES[_ACTIVE_THEME]
        apply_theme(resolved)
        self.configure(background=BG)
        self._build_style()
        self._tint_menus()
        self._retint_plain_widgets(previous)
        # (100x-158) the table chrome's stripe/hover tags + every live
        # figure toolbar follow the palette flip too
        refresh_table_chrome()
        for _host, toolbar in self._live_toolbars:
            with contextlib.suppress(tk.TclError):
                if toolbar.winfo_exists():
                    self._style_figure_toolbar(toolbar)
        # (100x-159) the metrics dialog's palette block follows the flip
        self._refresh_metrics_dialog()

    def _tint_menus(self) -> None:
        """Recolour the menu bar for the active palette."""
        for menu in self._menu_tints:
            with contextlib.suppress(tk.TclError):
                menu.configure(
                    background=HEADING if _ACTIVE_THEME == "dark" else CARD,
                    foreground=INK,
                    activebackground=ACCENT_SOFT,
                    activeforeground=INK,
                )

    def _retint_plain_widgets(self, previous: dict[str, str]) -> None:
        """Walk the widget tree recolouring plain ``tk`` widgets.

        Only widgets still carrying a colour from the *previous* palette
        are touched, which is what keeps matplotlib's white figure
        canvases (also ``Canvas``/white in light mode) safely alone: the
        scroll canvases use ``BG``, never ``CARD``.
        """

        def walk(widget: Any) -> None:
            for child in widget.winfo_children():
                klass = child.winfo_class()
                try:
                    if klass == "Frame":
                        if str(child.cget("background")) == previous["CARD"]:
                            child.configure(background=CARD)
                        if str(child.cget("background")) == previous["ACCENT"]:
                            # the card headers' 3px accent strips (100x-119)
                            child.configure(background=ACCENT)
                        if str(child.cget("highlightbackground")) == previous["BORDER"]:
                            child.configure(highlightbackground=BORDER)
                    elif klass == "Canvas":
                        if str(child.cget("background")) == previous["BG"]:
                            child.configure(background=BG)
                    elif klass == "Text":
                        if str(child.cget("background")) == previous["CARD"]:
                            child.configure(background=CARD, foreground=INK)
                    elif klass == "Button":
                        # (100x-158) the figure toolbars' plain tk buttons --
                        # matched by exact previous-palette colours so no
                        # other button in the window is ever touched.
                        if str(child.cget("background")) == previous["CARD"]:
                            child.configure(background=CARD)
                        if str(child.cget("activebackground")) == previous["ACCENT_SOFT"]:
                            child.configure(activebackground=ACCENT_SOFT)
                    elif klass == "Checkbutton":
                        # the mpl 3.10 toolbars' axis/grid toggles
                        if str(child.cget("background")) == previous["CARD"]:
                            child.configure(
                                background=CARD,
                                activebackground=CARD,
                            )
                    elif klass == "Label":
                        # the toolbars' coordinate-readout labels AND the PNG
                        # figure fallback labels (a latent dark-theme straggler
                        # before this branch existed)
                        if str(child.cget("background")) == previous["CARD"]:
                            child.configure(background=CARD)
                    elif klass == "Toplevel":
                        # (100x-159) the metrics dialog (and the card finder):
                        # their window background follows the flip too
                        if str(child.cget("background")) == previous["BG"]:
                            child.configure(background=BG)
                except tk.TclError:  # pragma: no cover - exotic widgets
                    pass
                walk(child)

        walk(self)

    # -- (100x-159) GUI metrics + palette inspector ------------------- #
    def _gui_metrics_snapshot(self) -> str:
        """The census/preferences text block the metrics dialog shows.

        Pure read-side: the widget census walks the live tree once
        (``_walk_widgets`` -- the same walk the chrome sweep uses), the
        card/tree/toolbar/job totals come from the registries that
        already exist, and the preferences line reads the four
        View-menu variables.  A SNAPSHOT, honestly labelled: live
        counters would burn CPU for nobody's benefit; the palette block
        below the text is the part that follows theme flips live.
        """
        cards = self._live_cards()
        live_keys: set[str] = set()
        folded: list[str] = []
        for card_key, entry in _COLLAPSE_CARDS.items():
            with contextlib.suppress(tk.TclError):
                if not bool(entry["shell"].winfo_exists()):
                    continue
            live_keys.add(card_key)
            if not bool(entry.get("expanded", True)):
                folded.append(card_key)
        trees = 0
        tree_rows = 0
        counts: dict[str, int] = {}
        for widget in self._walk_widgets(self):
            klass = widget.winfo_class()
            counts[klass] = counts.get(klass, 0) + 1
            if klass == "Treeview":
                trees += 1
                with contextlib.suppress(tk.TclError):
                    tree_rows += len(widget.get_children(""))
        try:
            queued = self._jobs.qsize()
        except NotImplementedError:  # pragma: no cover - exotic queues
            queued = 0
        session_file = session_path()
        if not self._persist_session:
            session_line = "session persistence off (--no-session)"
        elif session_file.exists():
            stamp = time.strftime(
                "%Y-%m-%d %H:%M", time.localtime(session_file.stat().st_mtime)
            )
            session_line = f"{session_file} \u00b7 last saved {stamp}"
        else:
            session_line = f"{session_file} \u00b7 not saved yet"
        lines = [
            f"CARDS      {len(cards)} live \u00b7 {len(live_keys)} collapsible \u00b7 {len(folded)} folded",
            f"TREES      {trees} Treeviews \u00b7 {tree_rows:,} rows",
            f"TOOLBARS   {len(self._live_toolbars)} live figure toolbars",
            f"JOBS       {'busy' if self._busy else 'idle'} \u00b7 queue \u2248 {queued} pending",
            (
                "PREFS      "
                f"theme {self._theme} (resolved {_ACTIVE_THEME}) \u00b7 "
                f"font {self._font_var.get()} pt \u00b7 "
                f"toolbars {'on' if self._toolbars_var.get() else 'off'} \u00b7 "
                f"shortcut hints {'on' if self._hints_var.get() else 'off'}"
            ),
            f"SESSION    {session_line}",
            "",
            "WIDGET CENSUS (by Tk class)",
        ]
        for klass, count in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])):
            lines.append(f"{klass:<12} {count:>7,}")
        return "\n".join(lines)

    def _show_gui_metrics(self) -> None:
        """View \u25b8 GUI metrics -- the census + the palette inspector.

        (100x-159) DearPyGui's developer tools (the metrics window, the
        theme inspector) translated honestly: the census is a snapshot
        at open, while the PALETTE block under it follows theme flips
        live -- every key of the active palette as a colour chip with
        its hex value, so "which colour is HOVER?" is one glance, not a
        source dive.  Re-opening lifts the existing dialog instead of
        stacking a second one.
        """
        if tk is None:  # pragma: no cover - headless import
            return
        existing = self._metrics_dialog
        if existing is not None:
            with contextlib.suppress(tk.TclError):
                if bool(existing.winfo_exists()):
                    existing.lift()
                    return
        win = tk.Toplevel(self)
        win.title("GUI metrics")
        win.configure(background=BG)
        win.transient(self)
        try:
            win.geometry(f"+{self.winfo_rootx() + 120}+{self.winfo_rooty() + 90}")
        except tk.TclError:  # pragma: no cover - unmapped parent
            pass
        ttk.Label(
            win,
            text="Widget census + preferences (a snapshot at open) -- "
            "the palette below follows theme flips live.",
            style="CardMuted.TLabel",
            wraplength=520,
            justify="left",
        ).pack(anchor="w", padx=14, pady=(12, 4))
        text = tk.Text(
            win,
            height=22,
            width=72,
            background=CARD,
            foreground=INK,
            relief="solid",
            borderwidth=1,
            highlightthickness=0,
            padx=8,
            pady=6,
            font=("TkFixedFont", 10),
            wrap="none",
        )
        text.insert("1.0", self._gui_metrics_snapshot())
        text.configure(state="disabled")
        text.pack(fill="x", padx=14, pady=(0, 8))
        Tooltip(
            text,
            "The widget census by Tk class, the card / tree / toolbar / "
            "job totals and the active preferences -- a snapshot from "
            "the moment the dialog opened.",
        )
        self._metrics_text = text
        self._metrics_palette_title = ttk.Label(
            win,
            text=f"Palette \u2014 {_ACTIVE_THEME} "
            f"({len(_PALETTES[_ACTIVE_THEME])} keys)",
            style="CardTitle.TLabel",
        )
        self._metrics_palette_title.pack(anchor="w", padx=14, pady=(0, 4))
        self._metrics_palette = ttk.Frame(win, style="Card.TFrame")
        self._metrics_palette.pack(fill="x", padx=14, pady=(0, 8))
        self._populate_metrics_palette()
        close = ttk.Button(win, text="Close", style="Ghost.TButton", command=win.destroy)
        close.pack(anchor="e", padx=14, pady=(0, 12))
        Tooltip(close, "Close the metrics dialog (View \u25b8 GUI metrics re-opens it).")
        self._metrics_dialog = win

    def _populate_metrics_palette(self) -> None:
        """(Re)build the palette chip grid -- one row per palette key."""
        holder = self._metrics_palette
        if holder is None:
            return
        with contextlib.suppress(tk.TclError):
            for child in holder.winfo_children():
                child.destroy()
        for row, (pal_key, value) in enumerate(sorted(_PALETTES[_ACTIVE_THEME].items())):
            chip = tk.Frame(
                holder,
                width=18,
                height=12,
                background=value,
                highlightbackground=BORDER,
                highlightthickness=1,
            )
            chip.grid(row=row, column=0, sticky="w", padx=(0, 8), pady=1)
            chip.pack_propagate(False)
            ttk.Label(holder, text=pal_key, style="Field.TLabel").grid(
                row=row, column=1, sticky="w"
            )
            ttk.Label(holder, text=value, style="CardMuted.TLabel").grid(
                row=row, column=2, sticky="w", padx=(10, 0)
            )
        holder.columnconfigure(2, weight=1)

    def _refresh_metrics_dialog(self) -> None:
        """Theme flips re-tint an open metrics dialog's palette block."""
        win = self._metrics_dialog
        if win is None:
            return
        try:
            alive = bool(win.winfo_exists())
        except tk.TclError:  # pragma: no cover - destroyed mid-flip
            alive = False
        if not alive:
            self._metrics_dialog = None
            self._metrics_palette = None
            self._metrics_text = None
            self._metrics_palette_title = None
            return
        self._populate_metrics_palette()
        with contextlib.suppress(tk.TclError):
            self._metrics_palette_title.configure(
                text=f"Palette \u2014 {_ACTIVE_THEME} "
                f"({len(_PALETTES[_ACTIVE_THEME])} keys)"
            )

    def _collect_session(self) -> dict[str, Any]:
        """Snapshot every input on every tab into a session payload."""
        variables: dict[str, Any] = {}
        for name, value in sorted(vars(self).items()):
            if name.startswith("_book") or name == "_theme_var":
                continue  # transient bookkeeping, not user input
            if isinstance(value, tk.Variable):
                with contextlib.suppress(tk.TclError):
                    variables[name] = value.get()
            elif isinstance(value, ttk.Entry):  # covers Spinbox/Combobox
                variables[name] = value.get()
        families = {family: bool(var.get()) for family, var in self._feat_family_vars.items()}
        texts = {
            "pasted": self._feat_pasted_text.get("1.0", "end-1c"),
            "corpus": self._corpus_text.get("1.0", "end-1c"),
            "smiles": self._dock_smiles_text.get("1.0", "end-1c"),
            "rism": self._rism_text.get("1.0", "end-1c"),
            "maccs": self._maccs_text.get("1.0", "end-1c"),
            "scan_refs": self._scan_ref_text.get("1.0", "end-1c"),
            "scan_lib": self._scan_lib_text.get("1.0", "end-1c"),
            # 100x-121: the Ctrl+F card finder's last query -- a plain
            # string (restored into the attribute, not a Text widget).
            "finder": getattr(self, "_finder_last_query", ""),
            # 100x-130: the finder's recency row -- a JSON-encoded list
            # of card titles (texts values are coerced to str, so the
            # list rides as JSON; the restore path parses tolerantly).
            "finder_recent": json.dumps(getattr(self, "_finder_recent", [])),
            # 100x-135: the picklist's order memory -- the same JSON-in-a
            # text trick, one dict of kind -> label list (the web twin's
            # localStorage key, mirrored onto the session file so the
            # memory survives restarts; the restore path parses
            # tolerantly and a foreign value resets it, never the app).
            "report_page_order": json.dumps(
                {
                    kind: [str(label) for label in labels]
                    for kind, labels in getattr(
                        self, "_report_page_order", {}
                    ).items()
                    if kind in ("table", "figure")
                    and isinstance(labels, list)
                }
            ),
            # 100x-159: which collapsible cards sit folded -- the same
            # JSON-in-a-text trick, one sorted list of stable card keys
            # (the restore path parses tolerantly; a foreign value just
            # leaves every card open, never a half-folded window).
            "collapsed_cards": json.dumps(collapsed_card_keys()),
        }
        try:
            tab = self._book.index(self._book.select())
        except tk.TclError:  # pragma: no cover - no tab selected yet
            tab = 0
        # (100x-142) the picked paths -- pure pickers only (see
        # _SESSION_PATH_ATTRS); dataset paths that need a reload stay
        # out on purpose.  getattr twice on purpose: the isinstance
        # guard must never leak an unrelated loop variable into str().
        paths = {
            name: str(getattr(self, name))
            for name in sorted(_SESSION_PATH_ATTRS)
            if isinstance(getattr(self, name, None), Path)
        }
        # (100x-144) the multi-file picks -- same discipline for the
        # three list-holding pickers; only genuine Path members ride,
        # in their picked order
        paths_multi: dict[str, list[str]] = {}
        for name in sorted(_SESSION_PATH_LIST_ATTRS):
            picked = getattr(self, name, None)
            if isinstance(picked, list):
                paths_multi[name] = [str(p) for p in picked if isinstance(p, Path)]
        return dump_session(
            theme=self._theme,
            geometry=self.geometry(),
            tab=tab,
            variables=variables,
            families=families,
            texts=texts,
            paths=paths,
            paths_multi=paths_multi,
        )

    def _write_session_file(self) -> bool:
        """Persist the current session; ``True`` when the file landed."""
        try:
            path = session_path()
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("w", encoding="utf-8") as handle:
                json.dump(self._collect_session(), handle, indent=2)
            return True
        except (OSError, TypeError, ValueError):
            return False

    def _save_session_now(self) -> None:
        """File ▸ Save session now -- write immediately and report."""
        if not self._persist_session:
            return
        if self._write_session_file():
            self._job_label.configure(text=f"session saved · {session_path()}")
        else:
            self._job_label.configure(text="session NOT saved (path unwritable)")

    def _clear_saved_session(self) -> None:
        """File ▸ Clear saved session -- forget the stored inputs."""
        if not self._persist_session:
            return
        removed = False
        with contextlib.suppress(OSError):
            session_path().unlink()
            removed = True
        self._session = None
        if messagebox is not None:
            messagebox.showinfo(
                "Session cleared",
                "The saved session was removed.\nFresh defaults return on the next launch."
                if removed
                else "No saved session file existed.",
            )

    def _clear_report_order(self) -> None:
        """File ▸ Clear remembered report order -- forget the picklist's memory.

        (100x-136) The order memory (100x-134, persisted by 100x-135)
        was forgettable from INSIDE the dialog only while a drift
        existed -- the dialog's Reset button disables itself at the
        walk order, so a reader who remembered an order wanted no
        dialog gymnastics to forget it.  This menu item is the
        always-available path: both kinds are dropped, the session
        file is written THROUGH immediately (the Reset relies on the
        close-time auto-save; this one does not wait -- the forget
        survives a crash), and the next picklist opens in the walking
        order with its confession quiet.  With ``persist_session=False``
        the memory was per-process anyway -- the message says so
        honestly, and the failed-write case confesses that the next
        LAUNCH will restore the order after all (the file still holds
        it).  A memory that never existed gets the honest "nothing to
        forget" -- never a silent no-op.
        """
        if not (
            self._report_page_order.get("table")
            or self._report_page_order.get("figure")
        ):
            if messagebox is not None:
                messagebox.showinfo(
                    "No remembered order",
                    "Nothing to forget yet.\n\n"
                    "Save a session report once and its page order is "
                    "remembered -- the next Save's checklist re-opens "
                    "pre-arranged, and this menu item forgets it.",
                )
            return
        self._report_page_order.pop("table", None)
        self._report_page_order.pop("figure", None)
        # (100x-138) the provenance dies with the memory -- a cleared
        # order is nobody's import any more
        self._report_order_origin = None
        wrote = self._write_session_file() if self._persist_session else False
        if messagebox is not None:
            if not self._persist_session:
                messagebox.showinfo(
                    "Remembered order cleared",
                    "The report checklist's remembered page order was "
                    "forgotten for this session.\n\n"
                    "Session saving is off, so the memory never reached "
                    "a file -- the next launch starts fresh regardless.",
                )
            elif wrote:
                messagebox.showinfo(
                    "Remembered order cleared",
                    "The report checklist's remembered page order was "
                    "forgotten.\n\n"
                    "The next Save opens in the walking order (tables "
                    "first, then figures), and the session file was "
                    "written -- the next launch forgets it too.",
                )
            else:
                messagebox.showinfo(
                    "Remembered order cleared",
                    "The report checklist's remembered page order was "
                    "forgotten -- the next Save opens in the walking order "
                    "(tables first, then figures).\n\n"
                    "The session file could not be written, so the next "
                    "launch restores the remembered order after all.",
                )
        self._job_label.configure(text="remembered report order cleared")

    def _export_report_order(self) -> None:
        """File ▸ Export remembered order -- share the picklist's memory.

        (100x-137) The order memory lived in exactly two places -- the
        process (100x-134) and the auto-saved session file (100x-135,
        which a full ``Export session…`` already carries) -- so sharing
        an order with a colleague meant sharing the WHOLE session:
        every input, every pasted corpus, every path.  This menu item
        writes the standalone artifact instead: a tiny JSON carrying
        only the format marker, the kind tag and the two label lists
        (``dump_report_order`` normalises), the preference without the
        inputs.  A memory that never existed gets the honest
        "nothing to share yet" -- never a silent no-op, never an empty
        file pretending to be one.  A failed write confesses on the
        job label exactly the way the session export does.
        """
        if not (
            self._report_page_order.get("table")
            or self._report_page_order.get("figure")
        ):
            if messagebox is not None:
                messagebox.showinfo(
                    "No remembered order",
                    "Nothing to share yet.\n\n"
                    "Save a session report once and its page order is "
                    "remembered -- this item writes that order to a "
                    "small file a colleague can import on their machine.",
                )
            return
        if filedialog is None:  # pragma: no cover - headless import
            return
        target = filedialog.asksaveasfilename(
            defaultextension=".json",
            initialfile="pharmaml-report-order.json",
            filetypes=[("Playground report order", "*.json"), ("All files", "*.*")],
            title="Export remembered report order",
        )
        if not target:
            return
        if export_session(dump_report_order(self._report_page_order), target):
            self._job_label.configure(text=f"report order exported · {target}")
        else:
            self._job_label.configure(
                text="report order NOT exported (path unwritable)"
            )

    def _import_report_order(self) -> None:
        """File ▸ Import remembered order -- adopt a shared order.

        (100x-137) The import side of the standalone artifact: a valid
        order file REPLACES the in-process memory (both kinds, the
        ``load_report_order`` normaliser's trusted dict) and writes the
        session file THROUGH immediately -- the same discipline as the
        Clear menu item, so the imported order survives a crash and the
        next LAUNCH re-opens pre-arranged exactly where the colleague
        left it.  A foreign or corrupt file (missing format marker,
        missing kind tag, unreadable JSON) is rejected with an honest
        error and the live memory is never touched.  A valid but EMPTY
        order is the honest reset: both kinds empty, the next picklist
        walks the walk order.  With ``persist_session=False`` the
        message says so -- the import lives in this process only.

        (100x-138) The adoption carries its PROVENANCE: the picklist's
        confession names the file the order arrived through ("The
        imported order from <file> was applied") until the reader
        completes their own Save (the order becomes theirs), resets,
        or clears.  The empty import confesses nothing -- an empty
        memory is nobody's import.  The provenance is process-local by
        design: after a restart the order arrives from the SESSION
        FILE, which IS the last saved order, and the confession says
        exactly that.
        """
        if filedialog is None:  # pragma: no cover - headless import
            return
        source = filedialog.askopenfilename(
            filetypes=[("Playground report order", "*.json"), ("All files", "*.*")],
            title="Import remembered report order",
        )
        if not source:
            return
        order = load_report_order(read_json_file(source))
        if order is None:
            if messagebox is not None:
                messagebox.showerror(
                    "Invalid report order file",
                    "That file is not a remembered report order "
                    "(format marker missing or unreadable).\n\n"
                    "The live order memory was not touched.",
                )
            return
        self._report_page_order = order
        # (100x-138) the PROVENANCE -- the file this order arrived
        # through; the next picklist's confession names it ("The
        # imported order from <file> was applied") until the reader
        # completes their own Save, Resets, or Clears.  The honest
        # EMPTY import clears it instead -- an empty memory is nobody's
        # import.
        self._report_order_origin = (
            str(source) if (order.get("table") or order.get("figure")) else None
        )
        wrote = self._write_session_file() if self._persist_session else False
        if messagebox is not None:
            tables = len(order.get("table", []))
            figures = len(order.get("figure", []))
            if not (tables or figures):
                messagebox.showinfo(
                    "Report order imported",
                    "The imported order is empty -- the next Save's "
                    "checklist opens in the walking order (tables "
                    "first, then figures).",
                )
            elif not self._persist_session:
                messagebox.showinfo(
                    "Report order imported",
                    f"The imported order was applied: {tables} table "
                    f"page{'s' if tables != 1 else ''} and {figures} "
                    f"figure page{'s' if figures != 1 else ''}.\n\n"
                    "Session saving is off, so the order lives in "
                    "this session only -- the next launch starts at "
                    "the walking order.",
                )
            elif wrote:
                messagebox.showinfo(
                    "Report order imported",
                    f"The imported order was applied: {tables} table "
                    f"page{'s' if tables != 1 else ''} and {figures} "
                    f"figure page{'s' if figures != 1 else ''}.\n\n"
                    "The next Save's checklist opens pre-arranged in "
                    "this order, and the session file was written -- "
                    "the next launch keeps it too.",
                )
            else:
                messagebox.showinfo(
                    "Report order imported",
                    f"The imported order was applied: {tables} table "
                    f"page{'s' if tables != 1 else ''} and {figures} "
                    f"figure page{'s' if figures != 1 else ''}.\n\n"
                    "The session file could not be written, so the next "
                    "launch restores the order that was there before.",
                )
        self._job_label.configure(text=f"report order imported · {source}")

    def _export_session(self) -> None:
        """File ▸ Export session -- write a shareable session file."""
        if filedialog is None:
            return
        target = filedialog.asksaveasfilename(
            defaultextension=".json",
            initialfile="pharmaml-playground-session.json",
            filetypes=[("Playground session", "*.json"), ("All files", "*.*")],
            title="Export playground session",
        )
        if not target:
            return
        if export_session(self._collect_session(), target):
            self._job_label.configure(text=f"session exported · {target}")
        else:
            self._job_label.configure(text="session NOT exported (path unwritable)")

    def _import_session(self) -> None:
        """File ▸ Import session -- apply a shareable session file."""
        if filedialog is None:
            return
        source = filedialog.askopenfilename(
            filetypes=[("Playground session", "*.json"), ("All files", "*.*")],
            title="Import playground session",
        )
        if not source:
            return
        session = load_session(read_json_file(source))
        if session is None:
            if messagebox is not None:
                messagebox.showerror(
                    "Invalid session file",
                    "That file is not a playground session (format marker missing or unreadable).",
                )
            return
        self._session = session
        self._restore_session()
        if session["theme"] in _THEMES and session["theme"] != self._theme:
            self._theme = session["theme"]
            if self._theme_var is not None:
                with contextlib.suppress(tk.TclError):
                    self._theme_var.set(self._theme)
            self._set_theme(self._resolve_auto_theme() if self._theme == "auto" else self._theme)
        self._job_label.configure(text=f"session imported · {source}")

    def _reset_current_tab(self) -> None:
        """File ▸ Reset current tab to defaults (Ctrl+Shift+R, 100x-54)."""
        try:
            index = self._book.index(self._book.select())
        except tk.TclError:  # pragma: no cover - no tab selected
            return
        self._reset_tab(index)

    def _session_text_widgets(self) -> dict[str, Any]:
        """The seven persisted text boxes as ONE shared map.

        (100x-142) The four text maps had drifted apart: the restore path
        knew all seven keys, the reset map carried five, the copy map a
        DIFFERENT five, and the ownership walk only four -- so the
        Chemistry tab's MACCS box and both similarity-scan boxes escaped
        "Reset to defaults" and "Copy inputs as JSON" while riding the
        session file all along.  One map, four consumers, no drift.
        """
        return {
            "pasted": self._feat_pasted_text,
            "corpus": self._corpus_text,
            "smiles": getattr(self, "_dock_smiles_text", None),
            "rism": getattr(self, "_rism_text", None),
            "maccs": getattr(self, "_maccs_text", None),
            "scan_refs": getattr(self, "_scan_ref_text", None),
            "scan_lib": getattr(self, "_scan_lib_text", None),
        }

    def _reset_tab(self, index: int) -> None:
        """Reset ONE tab's inputs to launch defaults (per-tab footer
        button, 100x-55; the File-menu command delegates here).

        Only the named tab's inputs are reset -- every other tab keeps
        its live values -- using the defaults snapshot taken right after
        the tabs were built (before any session restore).
        """
        names = self._tab_input_owners.get(index, set())
        defaults = self._session_defaults
        text_widgets = self._session_text_widgets()
        applied = 0
        for name in sorted(names):
            if name.startswith("family:"):
                family = name[len("family:") :]
                var = self._feat_family_vars.get(family)
                if family in defaults["families"] and var is not None:
                    with contextlib.suppress(tk.TclError):
                        var.set(bool(defaults["families"][family]))
                        applied += 1
                continue
            if name.startswith("text:"):
                key = name[len("text:") :]
                widget = text_widgets.get(key)
                if key in defaults["texts"] and widget is not None:
                    widget.delete("1.0", "end")
                    content = str(defaults["texts"][key])
                    if content:
                        widget.insert("1.0", content)
                    applied += 1
                continue
            if name not in defaults["variables"]:
                continue
            widget = getattr(self, name, None)
            value = defaults["variables"][name]
            if isinstance(widget, tk.Variable):
                with contextlib.suppress(tk.TclError):
                    widget.set(value)
                    applied += 1
            elif isinstance(widget, ttk.Entry):
                setter = getattr(widget, "set", None)
                if callable(setter):  # Spinbox / Combobox
                    setter(str(value))
                else:
                    widget.delete(0, "end")
                    if str(value):
                        widget.insert(0, str(value))
                applied += 1
        label = self._book.tab(index, "text")
        # the ML tab owns one DYNAMIC input -- the manual-hyperparameter
        # card.  Its JSON variable was reset with the others above; the
        # panel itself must be rebuilt to show it (100x-106).
        if label.strip() == "Data & ML":
            self._ml_params_var.set("{}")
            with contextlib.suppress(Exception):  # best effort
                self._ml_refresh_hyperparam_panel()
        # (100x-159) launch defaults mean EXPANDED cards too -- every
        # folded collapsible card on THIS tab unfolds with the reset
        # (other tabs keep their folds -- the per-tab rule).
        pages = [self._book.nametowidget(tab) for tab in self._book.tabs()]
        unfolded = 0
        for card_key, entry in _COLLAPSE_CARDS.items():
            shell = entry["shell"]
            with contextlib.suppress(tk.TclError):
                if (
                    not bool(entry.get("expanded", True))
                    and bool(shell.winfo_exists())
                    and self._card_tab_index(shell, pages) == index
                ):
                    _set_card_expanded(card_key, True)
                    unfolded += 1
        extra = f" · {unfolded} card(s) unfolded" if unfolded else ""
        self._job_label.configure(
            text=f"{label.lower()} tab reset · {applied} inputs back to defaults{extra}"
        )

    def _copy_tab_inputs(self, index: int) -> None:
        """Copy ONE tab's live inputs as a share-lite JSON snippet.

        The same ownership map the per-tab reset uses decides what
        belongs to the tab; values are read LIVE (not the launch
        defaults) and coerced the session's way, so the snippet is a
        plain ``{tab, variables, families, texts}`` dict -- paste it
        into an issue report, a script, or a message.
        """
        names = self._tab_input_owners.get(index, set())
        text_widgets = self._session_text_widgets()
        variables: dict[str, Any] = {}
        families: dict[str, bool] = {}
        texts: dict[str, str] = {}
        for name in sorted(names):
            if name.startswith("family:"):
                family = name[len("family:") :]
                var = self._feat_family_vars.get(family)
                if var is not None:
                    with contextlib.suppress(tk.TclError):
                        families[family] = bool(var.get())
                continue
            if name.startswith("text:"):
                key = name[len("text:") :]
                widget = text_widgets.get(key)
                if widget is not None:
                    texts[key] = widget.get("1.0", "end-1c")
                continue
            widget = getattr(self, name, None)
            if isinstance(widget, tk.Variable):
                with contextlib.suppress(tk.TclError):
                    variables[name] = widget.get()
            elif isinstance(widget, ttk.Entry):
                variables[name] = widget.get()
        label = self._book.tab(index, "text").strip()
        payload = {
            "tab": label,
            "variables": variables,
            "families": families,
            "texts": texts,
        }
        items = len(variables) + len(families) + len(texts)
        self._copy(json.dumps(payload, indent=2, sort_keys=True))
        self._job_label.configure(text=f"{label.lower()} inputs copied as JSON · {items} items")

    def _walk_widgets(self, widget: Any) -> Iterator[Any]:
        """Yield ``widget`` and every descendant (the GUI-tree walk)."""
        yield widget
        for child in widget.winfo_children():
            yield from self._walk_widgets(child)

    # -- (100x-158) DearPyGui affordances ----------------------------- #
    def _apply_table_chrome(self) -> None:
        """Attach zebra/hover/sort chrome to every tree the tabs built.

        One post-build walk covers all 29 statically created Treeviews;
        trees dialogs create later attach at their own creation sites
        (the card finder, the report picklists).
        """
        with contextlib.suppress(tk.TclError):
            for widget in self._walk_widgets(self):
                if isinstance(widget, ttk.Treeview):
                    attach_table_chrome(widget)

    def _style_figure_toolbar(self, toolbar: Any) -> None:
        """Recolour a matplotlib navigation toolbar to the active palette.

        The Tk toolbar mixes plain ``tk`` buttons, frames, checkbuttons
        (the mpl 3.10 axis/grid toggles) and the coordinate-readout
        labels -- every child class gets the card treatment.
        """
        with contextlib.suppress(tk.TclError):
            toolbar.configure(background=CARD, highlightthickness=0, borderwidth=0)
            for child in toolbar.winfo_children():
                with contextlib.suppress(tk.TclError):
                    klass = child.winfo_class()
                    if klass in ("Frame", "Labelframe"):
                        child.configure(background=CARD, highlightthickness=0, borderwidth=0)
                    elif klass == "Button":
                        child.configure(
                            background=CARD,
                            foreground=INK,
                            activebackground=ACCENT_SOFT,
                            activeforeground=INK,
                            highlightthickness=0,
                            borderwidth=0,
                        )
                    elif klass == "Checkbutton":
                        child.configure(
                            background=CARD,
                            foreground=INK,
                            activebackground=CARD,
                            activeforeground=INK,
                            highlightthickness=0,
                            borderwidth=0,
                        )
                    elif klass == "Label":
                        child.configure(background=CARD, foreground=MUTED)

    def _attach_figure_toolbar(self, host: Any, canvas: Any) -> Any:
        """The interactive-plot parity: a navigation toolbar under a figure.

        DearPyGui plots pan, zoom and box-select out of the box; the
        playground's embedded figures were static renders.  This bolts
        matplotlib's ``NavigationToolbar2Tk`` (home / pan / zoom / save +
        the live coordinate readout in its own message label) onto every
        TkAgg embed, styled to the palette.  Returns ``None`` (and the
        figure stays static-but-functional) when the preference is off
        or the toolbar cannot build on the host's Tk.
        """
        preference = getattr(self, "_toolbars_var", None)
        if preference is not None and not preference.get():
            return None
        try:
            from matplotlib.backends.backend_tkagg import NavigationToolbar2Tk
        except ImportError:  # pragma: no cover - TkAgg itself failed to load
            return None
        try:
            toolbar = NavigationToolbar2Tk(canvas, host, pack_toolbar=False)
        except Exception:  # noqa: BLE001 - exotic Tk builds keep the static figure
            return None
        with contextlib.suppress(Exception):  # update() is belt-only
            toolbar.update()
        # a re-render into the SAME host destroys the previous toolbar with
        # the host's children -- drop its stale registration (and any other
        # dead pair) so the list always mirrors the live windows
        self._live_toolbars[:] = [
            (live_host, live_toolbar)
            for live_host, live_toolbar in _toolbar_prune(self._live_toolbars)
            if live_host is not host
        ]
        self._style_figure_toolbar(toolbar)
        toolbar.pack(side="bottom", fill="x")
        self._live_toolbars.append((host, toolbar))
        return toolbar

    def _apply_toolbar_visibility(self) -> None:
        """View ▸ Figure toolbars: show/hide every live toolbar at once."""
        for _host, toolbar in self._live_toolbars:
            with contextlib.suppress(tk.TclError):
                if not toolbar.winfo_exists():
                    continue
                if self._toolbars_var.get():
                    toolbar.pack(side="bottom", fill="x")
                else:
                    toolbar.pack_forget()

    def _attach_crosshair(self, canvas: Any) -> None:
        """The cross-highlight parity: a dashed crosshair under the cursor.

        DearPyGui's ``is_cross_highlight`` draws a tracking cross with the
        coordinates read out live.  The toolbar already provides the
        readout (its message label); this adds the two dashed guides,
        drawn via ``add_artist`` so they NEVER join the axes' data limits
        (an ``add_line`` crosshair would autoscale the panel on the next
        draw -- the classic drift bug).  Hidden on leave; full redraw via
        ``draw_idle`` coalesces rapid motion into one repaint.
        """
        try:
            from matplotlib.lines import Line2D
        except ImportError:  # pragma: no cover - no matplotlib, no canvas
            return

        def pair_for(ax: Any) -> tuple[Any, Any]:
            existing = getattr(ax, "_pg_crosshair", None)
            if existing is not None:
                return existing
            vertical = Line2D(
                [], [], linestyle=(0, (4, 3)), linewidth=0.8, alpha=0.9, clip_on=True
            )
            horizontal = Line2D(
                [], [], linestyle=(0, (4, 3)), linewidth=0.8, alpha=0.9, clip_on=True
            )
            vertical.set_visible(False)
            horizontal.set_visible(False)
            ax.add_artist(vertical)
            ax.add_artist(horizontal)
            ax._pg_crosshair = (vertical, horizontal)
            return vertical, horizontal

        def hide() -> None:
            changed = False
            for ax in canvas.figure.axes:
                pair = getattr(ax, "_pg_crosshair", None)
                if pair is not None and pair[0].get_visible():
                    pair[0].set_visible(False)
                    pair[1].set_visible(False)
                    changed = True
            if changed:
                canvas.draw_idle()

        def on_motion(event: Any) -> None:
            ax = getattr(event, "inaxes", None)
            if ax is None:
                hide()
                return
            hide()
            vertical, horizontal = pair_for(ax)
            x0, x1 = ax.get_xlim()
            y0, y1 = ax.get_ylim()
            vertical.set_data([event.xdata, event.xdata], [y0, y1])
            horizontal.set_data([x0, x1], [event.ydata, event.ydata])
            vertical.set_color(MUTED)
            horizontal.set_color(MUTED)
            vertical.set_clip_box(ax.bbox)
            horizontal.set_clip_box(ax.bbox)
            vertical.set_visible(True)
            horizontal.set_visible(True)
            canvas.draw_idle()

        canvas.mpl_connect("motion_notify_event", on_motion)
        canvas.mpl_connect("figure_leave_event", lambda _event: hide())

    def _apply_font_size(self) -> None:
        """View ▸ Font size: rescale every named font at once.

        DearPyGui has a global font scale; tkinter has named fonts, which
        is nearly the same lever: ``TkDefaultFont`` / ``TkTextFont`` /
        ``TkMenuFont`` reconfigure live, every unstyled widget follows,
        and ``_build_style`` re-derives the bold/large variants from
        ``self._ui_font_size`` so the whole hierarchy grows together.
        Embedded matplotlib figures keep their own sizes (they are export
        artifacts, sized for paper).
        """
        try:
            size = int(self._font_var.get())
        except (tk.TclError, ValueError, AttributeError):
            return
        if size == self._ui_font_size:
            return
        self._ui_font_size = size
        for name in ("TkDefaultFont", "TkTextFont", "TkMenuFont"):
            with contextlib.suppress(tk.TclError):
                tkfont.nametofont(name).configure(size=size)
        with contextlib.suppress(tk.TclError):
            self._mono.configure(size=size)
            self._mono_result.configure(size=size + 2)
        self._build_style()

    def _tab_input_names(self) -> dict[int, set[str]]:
        """Map each notebook tab to the session-input names it owns.

        Ownership is decided by the widget tree: every entry / spinbox /
        combobox / checkbutton / radiobutton living inside a tab's frame
        contributes its linked variable (Tcl name -> app attribute), an
        entry stored directly as an attribute contributes that name, the
        feature-family checkboxes contribute ``family:<name>`` keys and
        the two pasted corpora contribute ``text:<key>`` keys.  The theme
        radio and notebook bookkeeping are excluded (not user inputs).
        """
        var_by_tcl_name: dict[str, str] = {}
        entry_by_id: dict[int, str] = {}
        for name, value in vars(self).items():
            if name.startswith("_book") or name == "_theme_var":
                continue
            if isinstance(value, tk.Variable):
                var_by_tcl_name[str(value)] = name
            elif isinstance(value, ttk.Entry):
                entry_by_id[id(value)] = name
        family_by_tcl_name = {
            str(var): f"family:{family}" for family, var in self._feat_family_vars.items()
        }
        text_widgets = self._session_text_widgets()
        text_by_id = {
            id(widget): f"text:{key}"
            for key, widget in text_widgets.items()
            if widget is not None
        }
        owners: dict[int, set[str]] = {}
        with contextlib.suppress(tk.TclError):
            for index, tab_id in enumerate(self._book.tabs()):
                names: set[str] = set()
                for widget in self._walk_widgets(self._book.nametowidget(tab_id)):
                    if id(widget) in text_by_id:
                        names.add(text_by_id[id(widget)])
                        continue
                    if isinstance(widget, ttk.Entry):
                        linked = str(widget.cget("textvariable"))
                        if linked and linked in var_by_tcl_name:
                            names.add(var_by_tcl_name[linked])
                        elif id(widget) in entry_by_id:
                            names.add(entry_by_id[id(widget)])
                    elif isinstance(
                        widget, (ttk.Checkbutton, ttk.Radiobutton, tk.Checkbutton, tk.Radiobutton)
                    ):
                        linked = str(widget.cget("variable"))
                        if linked in var_by_tcl_name:
                            names.add(var_by_tcl_name[linked])
                        elif linked in family_by_tcl_name:
                            names.add(family_by_tcl_name[linked])
                owners[index] = names
        return owners

    def _restore_session(self) -> bool:
        """Re-apply the saved session onto the freshly built tabs.

        Returns ``True`` when a geometry was restored (so ``__init__``
        can skip re-centering the window).  Restore never raises: a
        payload naming a widget that no longer exists (older session,
        renamed attribute) is simply skipped.
        """
        if not self._session:
            return False
        session = self._session
        for name, value in session["variables"].items():
            widget = getattr(self, name, None)
            if isinstance(widget, tk.Variable):
                with contextlib.suppress(tk.TclError):
                    widget.set(value)
            elif isinstance(widget, ttk.Entry):
                setter = getattr(widget, "set", None)
                if callable(setter):  # Spinbox / Combobox
                    setter(str(value))
                else:
                    widget.delete(0, "end")
                    widget.insert(0, str(value))
        for family, checked in session["families"].items():
            var = self._feat_family_vars.get(family)
            if var is not None:
                with contextlib.suppress(tk.TclError):
                    var.set(bool(checked))
        # the hint row's visibility rides a tk.Variable, so a restored
        # session may have flipped it -- re-apply after the variables.
        self._apply_hint_visibility()
        # (100x-158) the UI font size rides one too (View > Font size) --
        # re-derive the named fonts + style hierarchy after the restore.
        with contextlib.suppress(Exception):  # never block a restore
            self._apply_font_size()
        text_widgets = self._session_text_widgets()
        for key, content in session["texts"].items():
            if key == "finder":
                # 100x-121: the finder's last query -- an attribute, not a
                # Text widget; older sessions simply lack the key.
                self._finder_last_query = str(content)
                continue
            if key == "finder_recent":
                # 100x-130: the recency row's memory -- a JSON list of
                # card titles, parsed tolerantly (a corrupt or foreign
                # value resets the memory, never the restore).
                try:
                    remembered = json.loads(content)
                except (TypeError, ValueError):
                    remembered = []
                if isinstance(remembered, list) and all(
                    isinstance(title, str) for title in remembered
                ):
                    self._finder_recent = remembered[:_FINDER_RECENT_MAX]
                continue
            if key == "report_page_order":
                # 100x-135: the picklist's order memory -- a JSON dict of
                # kind -> label list, parsed with the SAME tolerance (a
                # corrupt or foreign value resets the memory to the
                # walk order, never the restore); only the two real
                # kinds survive, each label coerced to str, so the
                # attribute never carries a half-typed payload.
                try:
                    stored = json.loads(content)
                except (TypeError, ValueError):
                    stored = {}
                if isinstance(stored, dict):
                    self._report_page_order = {
                        str(kind): [str(label) for label in labels]
                        for kind, labels in stored.items()
                        if kind in ("table", "figure")
                        and isinstance(labels, list)
                        and all(isinstance(label, str) for label in labels)
                    }
                continue
            if key == "collapsed_cards":
                # 100x-159: the collapsible cards' fold state -- a JSON
                # list of stable card keys parsed with the SAME
                # tolerance (a corrupt value leaves everything open);
                # unknown keys (renamed cards, older sessions) skip
                # quietly, exactly like every other tolerant restore.
                try:
                    stored_cards = json.loads(content)
                except (TypeError, ValueError):
                    stored_cards = []
                if isinstance(stored_cards, list):
                    for card_key in stored_cards:
                        if isinstance(card_key, str) and card_key in _COLLAPSE_CARDS:
                            _set_card_expanded(card_key, False)
                continue
            widget = text_widgets.get(key)
            if widget is not None:
                widget.delete("1.0", "end")
                widget.insert("1.0", content)
        tab = session["tab"]
        if 0 <= tab < self._book.index("end"):
            self._book.select(tab)
        # (100x-142) the picked paths come back ONLY when they still
        # exist on this machine (a mailed session, a moved folder, a
        # deleted campaign tree all degrade to the honest un-picked
        # state); a live pick is never overwritten.
        restored_paths = 0
        # .get(): hand-built payloads (older tests, foreign callers) may
        # carry no paths key at all -- the restore degrades to a no-op.
        for name, raw_path in session.get("paths", {}).items():
            if name not in _SESSION_PATH_ATTRS:
                continue
            if getattr(self, name, None) is not None:
                continue
            candidate = Path(raw_path)
            if candidate.exists():
                setattr(self, name, candidate)
                restored_paths += 1
        # (100x-144) the multi-file picks -- per-file existence filter
        # (the survivors keep their picked order; a vanished file drops
        # out instead of poisoning the run), a live non-empty pick is
        # never overwritten, and only allowlisted attrs ever land.
        for name, raw_files in session.get("paths_multi", {}).items():
            if name not in _SESSION_PATH_LIST_ATTRS:
                continue
            current = getattr(self, name, None)
            if isinstance(current, list) and current:
                continue  # the user re-picked this session -- keep theirs
            kept = [Path(p) for p in raw_files if Path(p).exists()]
            if kept:
                setattr(self, name, kept)
                restored_paths += len(kept)
        if restored_paths:
            self._refresh_restored_path_labels()
            self._job_label.configure(
                text=(
                    f"session restored · {restored_paths} picked path(s) "
                    "back · File ▸ Clear saved session resets"
                )
            )
        elif session["variables"] or session["texts"]:
            self._job_label.configure(text="session restored · File ▸ Clear saved session resets")
        restored_geometry = False
        parsed = parse_geometry(session["geometry"])
        if parsed is not None:
            width, height, x, y = parsed
            width = min(width, self.winfo_screenwidth())
            height = min(height, self.winfo_screenheight())
            on_screen = 0 <= x < self.winfo_screenwidth() and 0 <= y < self.winfo_screenheight()
            spec = f"{width}x{height}" + (f"+{x}+{y}" if on_screen else "")
            with contextlib.suppress(tk.TclError):
                self.geometry(spec)
                restored_geometry = True
        # the ML tab's manual-hyperparameter card is DYNAMIC (rebuilt
        # per model selection, values carried by the JSON variable the
        # loop above already restored) -- rebuild it once, after the
        # comboboxes hold their restored selections (100x-106).
        with contextlib.suppress(Exception):  # never block restore
            self._ml_refresh_hyperparam_panel()
        # (100x-122) same discipline for the swapped rows: a restored RL
        # method or reference-driven objective must re-sync its frames
        # (fixes the latent restore bug where the GA block stayed visible
        # under an RL selection, and hides/shows the reference row).
        with contextlib.suppress(Exception):  # never block restore
            self._on_method_change()
            self._objective_hint()
        return restored_geometry

    def _refresh_restored_path_labels(self) -> None:
        """Re-render every picker's info label after a path restore.

        (100x-142) The pick handlers configure their labels inline, so
        a restored path needs the same text the picker would have
        written.  The four cards that OWN a refresh helper reuse it
        (one rule per card); every other label is set with the picker's
        exact format, each guarded so one missing widget can never
        abort the rest of the restore.
        """

        def _label(attr: str, text: str) -> None:
            widget = getattr(self, attr, None)
            if widget is not None:
                with contextlib.suppress(tk.TclError):
                    widget.configure(text=text)

        def _name_of(attr: str) -> str:
            value = getattr(self, attr, None)
            return value.name if isinstance(value, Path) else "—"

        # cards with their own refresh helper -- one rule each
        for helper in (
            "_dock_refresh_campaign_info",
            "_dock_refresh_vina_info",
            "_dock_vbatch_refresh_info",
            "_dock_mgl_refresh_info",
            # (100x-143) the Utilities cards' own helpers: seven picked
            # paths ride the session across merge & split / table compare
            # / campaign file tools, but their four info labels kept the
            # launch placeholders after a restore -- the run silently used
            # the restored paths while the label denied them (the audit's
            # §1 finding; round 27's own "every restored path re-renders
            # its picker's info label" promise, finally kept).
            "_util_merge_mode_changed",
            "_util_cmp_refresh_info",
            "_util_tool_mode_changed",
        ):
            with contextlib.suppress(Exception):
                getattr(self, helper)()
        # inline-format labels -- the pickers' own text, verbatim
        if isinstance(self._dock_out_dir, Path):
            _label("_dock_out_info", f"campaign output: {self._dock_out_dir}")
        if isinstance(self._dock_receptor_source, Path):
            _label("_dock_receptor_info", self._dock_receptor_source.name)
        if isinstance(self._dock_ligand_path, Path):
            _label("_dock_ligand_info", self._dock_ligand_path.name)
        if isinstance(self._dock_smi_out, Path):
            _label("_dock_smi_info", f"output: {self._dock_smi_out}")
        if isinstance(self._dock_gen_out, Path):
            _label("_dock_gen_out_info", f"output: {self._dock_gen_out}")
        if isinstance(self._dock_smiles_receptor, Path):
            _label("_dock_smiles_receptor_info", str(self._dock_smiles_receptor))
        if isinstance(self._dock_smiles_out, Path):
            _label("_dock_smiles_out_info", f"campaign output: {self._dock_smiles_out}")
        if isinstance(self._dock_audit_gpf, Path) or isinstance(self._dock_audit_folder, Path):
            gpf = str(self._dock_audit_gpf) if isinstance(self._dock_audit_gpf, Path) else None
            folder = (
                str(self._dock_audit_folder) if isinstance(self._dock_audit_folder, Path) else None
            )
            text = ""
            if gpf:
                text += f"GPF: {gpf}"
            if folder:
                text += ("\n" if text else "") + f"folder: {folder}"
            _label("_dock_audit_info", text)
        if isinstance(self._conv_input, Path) or isinstance(self._conv_output, Path):
            _label(
                "_conv_info",
                f"input: {_name_of('_conv_input')}\noutput: {_name_of('_conv_output')}",
            )
        # (100x-143) the reindex card's picker writes the FULL path into
        # its label -- the restore now writes the same text (the fourth
        # Utilities label of the audit's §1 finding).
        if isinstance(getattr(self, "_util_reindex_path", None), Path):
            _label("_util_reindex_info", str(self._util_reindex_path))
        # (100x-144) the approval card's picker writes its list inline
        # (no mode-changed helper of its own) -- the restore mirrors the
        # picker's exact format so a restored list of approval exports
        # confesses itself like a fresh pick would.
        appr_files = [
            p for p in getattr(self, "_util_appr_files", []) if isinstance(p, Path)
        ]
        if appr_files:
            shown = ", ".join(p.name for p in appr_files[:3])
            if len(appr_files) > 3:
                shown += f" … (+{len(appr_files) - 3})"
            _label("_util_appr_info", shown)

    def _on_close(self) -> None:
        """Window close: save the session (unless disabled), then exit."""
        if self._persist_session:
            self._write_session_file()
        self.destroy()

    # -- menu actions ---------------------------------------------------- #
    def _menu_open_csv(self) -> None:
        # (100x-142) the busy guard: Ctrl+O stayed live during a job and
        # _ml_load_path swapped self._ml_frame synchronously while the
        # running worker thread was still reading it -- a narrow but
        # real race (KeyError on the swapped target, or silent training
        # against the new frame).  The action buttons are disabled for
        # exactly this reason; the menu accelerator now obeys the same
        # rule.
        if self._busy:
            messagebox.showinfo(
                "Busy",
                "A calculation is still running -- wait for it before "
                "opening another dataset.",
            )
            return
        self._book.select(self._ml_page)
        self._ml_open_csv()

    def _menu_save_figure(self) -> None:
        if self._last_figure is None:
            messagebox.showinfo("No figure yet", "Run a calculation that draws one first.")
            return
        if not self._require_pharmaml():
            return
        path = filedialog.asksaveasfilename(
            title="Save figure",
            defaultextension=".png",
            filetypes=[
                ("PNG figure", "*.png"),
                ("SVG figure", "*.svg"),
                ("PDF figure", "*.pdf"),
            ],
        )
        if not path:
            return
        try:
            from pharmaml.viz import save_figure

            saved = save_figure(self._last_figure, path)
            messagebox.showinfo("Figure saved", f"Written to\n{saved}")
        except Exception as exc:  # noqa: BLE001
            self._show_error("Could not save the figure", exc)

    def _session_report_picklist(
        self, live: list[list], tables: list[tuple[str, list[str], list[list[str]]]]
    ) -> tuple[list[list], list[tuple[str, list[str], list[list[str]]]]] | None:
        """The pre-save checklist both session-report menus consult.

        (100x-132) The web twin's report card gained its per-section
        control in 100x-131 (toggle chips, localStorage-persisted); the
        desktop's groups differ -- it walks LIVE pages, one figure page
        per card render plus one text page per filled table -- so the
        desktop twin is a pre-save dialog: every page the walk found is
        listed with a checkbox, all on by default, and the caller ships
        only the kept pages.  Returns ``(kept_live, kept_tables)`` or
        ``None`` when the user cancelled (no save started at all).

        The dialog carries a LIVE census footer ("N of M pages will
        ship") that recounts on every checkbox flip, and the Save
        button disables itself at zero pages -- the honest empty, the
        same contract as the web twin's "Nothing would ship" line.

        (100x-133) The pages REORDER -- the desktop twin of the web
        report card's draggable chips: every row carries ▲ / ▼ buttons
        that move it among its OWN kind's neighbours (a figure never
        crosses into the table block, because both walkers ship the
        kinds separately).  The rows are offered in the WALKING order
        -- the table pages first, then the figure pages, exactly the
        sequence ``save_pdf_report`` / the HTML builder writes them --
        and the returned lists carry the dialog's order, so the report
        walks the pages the way this list reads them.  The boundary
        buttons disable honestly (the first row's ▲ is a no-op), the
        numbering re-writes itself on every move, and a muted note
        under the header says what the order means.

        (100x-134) The order REMEMBERS -- the web twin persists its
        walking order per browser; the desktop twin now keeps the last
        SAVED dialog order per session (``_report_page_order``): the
        next Save's picklist re-opens with each kind's pages already
        in the remembered order (labels that no longer exist are
        skipped; a NEW page rides after the remembered ones, in walk
        order), a muted line under the header confesses the memory,
        and the dialog's own "Reset to walking order" button clears
        it (the web twin's dashed Reset chip, mirrored) -- the walk
        order returns and the memory is forgotten.  Cancel never
        touches the memory; only a completed Save rewrites it.

        (100x-135) The memory now survives RESTARTS: ``_collect_session``
        serialises it as the ``report_page_order`` text key (JSON, like
        the finder's recency row) and ``_restore_session`` replants it
        before the first picklist ever opens -- the web twin's
        localStorage, mirrored onto the session file.  The Reset
        button's forget is symmetric: the attribute empties, the
        close-time auto-save writes the empty state, and the next
        LAUNCH starts at the walk order.  A corrupt or foreign file
        value resets the memory, never the restore.

        (100x-136) The memory is forgettable WITHOUT the dialog too:
        File ▸ Clear remembered report order drops both kinds and
        writes the session file through immediately (the Reset's
        forget rides the close-time auto-save; this one does not
        wait), so the next picklist -- this session or the next
        launch -- opens in the walking order.  The dialog's Reset
        stays the in-dialog path (drift-honest); the menu item is the
        always-available one.

        (100x-137) The memory is SHAREABLE without the session: File
        ▸ Export remembered order writes the standalone artifact
        (``dump_report_order`` -- the two label lists and nothing
        else), and Import remembered order adopts one through
        ``load_report_order`` (a foreign file never reaches the
        attribute) and writes the session through immediately, so an
        imported order survives crashes and restarts exactly like a
        remembered one.

        (100x-138) The confession names its PROVENANCE: an order that
        arrived through Import says so -- "The imported order from
        <file> was applied" -- until the reader completes their own
        Save (the order becomes theirs and the wording returns to
        "Your last saved order"), resets, or clears.  A restart
        restores from the session file, which IS the last saved
        order, so a fresh launch never claims an import.
        """
        if tk is None:  # pragma: no cover - headless import
            return live, tables
        win = tk.Toplevel(self)
        win.title("Session report contents")
        win.configure(background=BG)
        win.transient(self)
        try:
            win.geometry(f"+{self.winfo_rootx() + 120}+{self.winfo_rooty() + 90}")
        except tk.TclError:  # pragma: no cover - unmapped parent
            pass
        win.bind("<Escape>", lambda _e: win.destroy())

        ttk.Label(
            win,
            text="Choose the pages the report ships — every page is on by default.",
            style="CardMuted.TLabel",
        ).pack(anchor="w", padx=16, pady=(14, 2))
        # (100x-133) the walking-order confession: the list below IS
        # the order the report writes its pages, so a reorder is a
        # promise, not a suggestion.
        ttk.Label(
            win,
            text=(
                "This list is the report's walking order — the table pages "
                "ship first, then the figure pages.  The ▲ / ▼ buttons on a "
                "row move it within its own group; the numbering follows."
            ),
            style="CardMuted.TLabel",
            wraplength=430,
            justify="left",
        ).pack(anchor="w", padx=16, pady=(0, 6))
        # (100x-134) the order-memory confession -- only shown when a
        # remembered order actually moved something, so a first Save
        # (or a Reset) keeps the dialog's original quiet.
        memory_label = ttk.Label(win, style="CardMuted.TLabel")
        memory_label.pack(anchor="w", padx=16, pady=(0, 6))

        body = ttk.Frame(win, style="Card.TFrame")
        body.pack(fill="both", expand=True, padx=16)
        # (100x-133) one sub-frame PER GROUP: repacking a row on a move
        # forgets and re-packs it inside its own group, so a row can
        # never escape into the other kind's block.
        table_group = ttk.Frame(body, style="Card.TFrame")
        figure_group = ttk.Frame(body, style="Card.TFrame")
        table_group.pack(fill="x", pady=(0, 4))
        figure_group.pack(fill="x", pady=(0, 4))
        # each record: the checkbox var, the walked entry, the raw label
        # (for renumbering), the row frame and its two arrow buttons
        records: dict[str, list[dict[str, Any]]] = {"table": [], "figure": []}

        def add_group(parent: Any, heading: str, count: int) -> None:
            row = ttk.Frame(parent, style="Card.TFrame")
            row.pack(fill="x", pady=(0, 4))
            ttk.Label(
                row,
                text=f"{heading} — {count} page{'s' if count != 1 else ''}",
                style="Field.TLabel",
            ).pack(side="left")

        def add_items(
            parent: Any,
            entries: list[Any],
            labels: list[str],
            kind: str,
            prefix: str,
        ) -> None:
            for label, entry in zip(labels, entries):
                var = tk.BooleanVar(value=True)
                row = ttk.Frame(parent, style="Card.TFrame")
                row.pack(fill="x", padx=(10, 0), pady=(0, 2))
                check = ttk.Checkbutton(
                    row,
                    text="",  # refresh_numbering writes the numbered text
                    variable=var,
                    command=refresh_census,
                )
                check.pack(side="left", anchor="w")
                arrows = ttk.Frame(row, style="Card.TFrame")
                arrows.pack(side="right")
                record: dict[str, Any] = {
                    "var": var,
                    "entry": entry,
                    "label": str(label),
                    "row": row,
                    "check": check,
                    "kind": kind,
                    "prefix": prefix,
                }
                up = ttk.Button(
                    arrows,
                    text="▲",
                    width=2,
                    command=partial(shift, record, -1),
                )
                up.pack(side="left", padx=(2, 0))
                down = ttk.Button(
                    arrows,
                    text="▼",
                    width=2,
                    command=partial(shift, record, 1),
                )
                down.pack(side="left")
                record["up"] = up
                record["down"] = down
                records[kind].append(record)

        def shift(record: dict[str, Any], delta: int) -> None:
            """Move one page one slot among its OWN kind's rows."""
            bucket = records[record["kind"]]
            index = bucket.index(record)
            target = index + delta
            if not 0 <= target < len(bucket):
                return  # the boundary is honest -- the button is disabled
            bucket[index], bucket[target] = bucket[target], bucket[index]
            # pack appends in call order, so forget-everything-then-pack
            # rewrites the group's visual order; the heading stays above
            # (it was packed first and is never forgotten)
            for other in bucket:
                other["row"].pack_forget()
            for other in bucket:
                other["row"].pack(fill="x", padx=(10, 0), pady=(0, 2))
            refresh_numbering()
            refresh_arrows()

        def refresh_numbering() -> None:
            for kind in ("table", "figure"):
                for position, other in enumerate(records[kind], start=1):
                    other["check"].configure(
                        text=(
                            f"{other['prefix']}{position} · "
                            f"{_truncate_caption_text(other['label'], 56)}"
                        )
                    )

        def refresh_arrows() -> None:
            for kind in ("table", "figure"):
                bucket = records[kind]
                for position, other in enumerate(bucket):
                    other["up"].state(
                        ["!disabled"] if position else ["disabled"]
                    )
                    other["down"].state(
                        ["!disabled"]
                        if position < len(bucket) - 1
                        else ["disabled"]
                    )
            # (100x-134) the Reset button rides the same refresh: it is
            # enabled exactly while the dialog's order has DRIFTED from
            # the walk order (a remembered order applied, or a manual
            # ▲ / ▼ move) -- at the walk order it disables itself, the
            # same honesty as the boundary arrows.
            drifted = False
            for kind in ("table", "figure"):
                ranks = [
                    walk_rank.get(id(other["entry"]), len(walk_rank))
                    for other in records[kind]
                ]
                if ranks != sorted(ranks):
                    drifted = True
            reset_button.state(["!disabled"] if drifted else ["disabled"])

        def refresh_census() -> None:
            kept = sum(
                1
                for kind in ("table", "figure")
                for other in records[kind]
                if other["var"].get()
            )
            total = sum(len(records[kind]) for kind in ("table", "figure"))
            census_label.configure(
                text=(
                    f"{kept} of {total} page{'s' if total != 1 else ''} will ship"
                    if kept
                    else "Nothing would ship — tick at least one page."
                )
            )
            if kept:
                save_button.state(["!disabled"])
            else:
                save_button.state(["disabled"])

        # (100x-134) apply the remembered order BEFORE any row exists:
        # reorder the walked lists per kind (stored labels first, in
        # stored order; labels the walk no longer finds are skipped -- a
        # re-rendered card, a cleared table; NEW labels ride after, in
        # walk order), then build the rows from the ordered lists.  The
        # dialog opens pre-arranged and the ▲ / ▼ machinery is untouched.
        def ordered(
            kind: str, entries: list[Any], labels: list[str]
        ) -> tuple[list[Any], list[str]]:
            remembered = self._report_page_order.get(kind) or []
            if not remembered:
                return entries, labels
            pairs = list(zip(entries, labels))
            used = [False] * len(pairs)
            kept: list[tuple[Any, str]] = []
            for name in remembered:
                for index, (entry, label) in enumerate(pairs):
                    if not used[index] and label == name:
                        used[index] = True
                        kept.append((entry, label))
                        break
            rest = [pair for index, pair in enumerate(pairs) if not used[index]]
            combined = kept + rest
            return [entry for entry, _label in combined], [label for _e, label in combined]

        table_labels_walk = [title for title, _headings, _rows in tables]
        figure_labels_walk = [str(entry[1]) for entry in live]
        table_entries, table_labels = ordered("table", list(tables), table_labels_walk)
        figure_entries, figure_labels = ordered("figure", list(live), figure_labels_walk)
        remembered_applied = bool(
            self._report_page_order.get("table")
            or self._report_page_order.get("figure")
        )
        if remembered_applied:
            # (100x-138) the confession names its PROVENANCE -- an order
            # that arrived through File ▸ Import remembered order says
            # so (the file's name, truncated the honest way), until the
            # reader completes their own Save / Resets / Clears; the
            # session-file restore IS the last saved order, so it keeps
            # the original wording.
            origin = getattr(self, "_report_order_origin", None)
            if origin:
                memory_label.configure(
                    text=(
                        f"The imported order from "
                        f"{_truncate_caption_text(Path(origin).name, 40)} "
                        "was applied — Reset to walking order forgets it."
                    ),
                    wraplength=430,
                    justify="left",
                )
            else:
                memory_label.configure(
                    text=(
                        "Your last saved order was applied — Reset to "
                        "walking order forgets it."
                    ),
                    wraplength=430,
                    justify="left",
                )
        else:
            memory_label.pack_forget()  # nothing remembered: stay quiet
        # (100x-134) the WALK order frozen for the Reset button: every
        # entry's rank in the registry walk, so "Reset to walking
        # order" can honestly restore what the dialog would have shown
        # with no memory and no moves.
        walk_rank: dict[int, int] = {}
        for position, entry in enumerate(list(tables) + list(live)):
            walk_rank[id(entry)] = position

        def reset_to_walk() -> None:
            """(100x-134) Restore the walk order AND forget the memory."""
            for kind in ("table", "figure"):
                bucket = records[kind]
                if not bucket:
                    continue
                bucket.sort(
                    key=lambda other: walk_rank.get(
                        id(other["entry"]), len(walk_rank)
                    )
                )
                for other in bucket:
                    other["row"].pack_forget()
                for other in bucket:
                    other["row"].pack(fill="x", padx=(10, 0), pady=(0, 2))
            refresh_numbering()
            refresh_arrows()
            memory_label.pack_forget()  # the confession no longer applies
            # the memory itself is forgotten -- the NEXT dialog opens in
            # the walk order too (the web twin's dashed Reset chip,
            # mirrored: it deletes the persisted key, not just the drift)
            self._report_page_order.pop("table", None)
            self._report_page_order.pop("figure", None)
            # (100x-138) the provenance dies with the memory (the Reset
            # forgets the import the same way it forgets the reader's)
            self._report_order_origin = None

        # (100x-133) the groups ride in the WALKING order -- both walkers
        # (the library's save_pdf_report and the HTML menu's builder)
        # write the table pages before the figure pages, so the dialog
        # lists the table block first: what the reader sees is what the
        # file gets.
        if tables:
            add_group(table_group, "Tables (one page each)", len(tables))
            add_items(
                table_group,
                entries=table_entries,
                labels=table_labels,
                kind="table",
                prefix="table ",
            )
        if live:
            add_group(figure_group, "Figures (one page each)", len(live))
            add_items(
                figure_group,
                entries=figure_entries,
                labels=figure_labels,
                kind="figure",
                prefix="figure ",
            )

        census_label = ttk.Label(win, style="CardMuted.TLabel")
        census_label.pack(anchor="w", padx=16, pady=(10, 4))
        buttons = ttk.Frame(win, style="Card.TFrame")
        buttons.pack(fill="x", padx=16, pady=(0, 14))
        outcome: dict[str, Any] = {"saved": False}

        def confirm() -> None:
            # zero pages never saves -- the button is disabled at zero,
            # but a keyboard/programmatic activation gets the same guard
            if not any(
                other["var"].get()
                for kind in ("table", "figure")
                for other in records[kind]
            ):
                return
            outcome["saved"] = True
            # (100x-134) the ORDER MEMORY -- a completed Save records the
            # dialog's per-kind order (ALL labels, kept or not: an
            # unchecked page keeps its place for the next visit).  The
            # returned lists stay exactly what they were.
            self._report_page_order["table"] = [
                str(other["label"]) for other in records["table"]
            ]
            self._report_page_order["figure"] = [
                str(other["label"]) for other in records["figure"]
            ]
            # (100x-138) the completed Save makes the order the READER'S
            # own -- the import's provenance confession retires with it
            # (the next picklist says "Your last saved order" again)
            self._report_order_origin = None
            win.destroy()

        save_button = ttk.Button(buttons, text="Save report…", command=confirm)
        save_button.pack(side="right")
        ttk.Button(buttons, text="Cancel", command=win.destroy).pack(
            side="right", padx=(0, 8)
        )
        # (100x-134) the Reset button -- the web twin's dashed chip on
        # the desktop: restores the walk order, forgets the memory.  Its
        # enabled/disabled state rides refresh_arrows (drift-honest).
        reset_button = ttk.Button(
            buttons,
            text="Reset to walking order",
            command=reset_to_walk,
        )
        reset_button.pack(side="left")
        refresh_numbering()
        refresh_arrows()
        refresh_census()
        win.protocol("WM_DELETE_WINDOW", win.destroy)
        win.grab_set()
        win.wait_window()
        if not outcome["saved"]:
            return None
        # the kept pages in the DIALOG's order -- the walking order
        kept_tables = [
            other["entry"] for other in records["table"] if other["var"].get()
        ]
        kept_live = [
            other["entry"] for other in records["figure"] if other["var"].get()
        ]
        return kept_live, kept_tables

    def _menu_save_session_report(self) -> None:
        """File ▸ Save session report -- one PDF of the session on screen.

        (100x-122) Composes :func:`pharmaml.viz.save_pdf_report` over the
        session figure registry: a title page with the census and stamp,
        then one page per live figure (a figure replaced on its card is
        gone -- the host now shows the newer render, and the report says
        so honestly).  ``close=False``: the on-screen figures stay alive.

        (100x-123) The report gained its TABLE axis: every filled table
        on screen (leaderboards, prediction sheets, descriptor panels,
        docking results -- any card's table with rows) is walked the
        same way the registry walks hosts and shipped through
        ``save_pdf_report(tables=...)`` as REAL text pages -- searchable,
        selectable, the library's own truncation note and all -- so the
        PDF is the session's whole record, pictures AND numbers.

        (100x-129) The report gained its INK VARIANT, riding the View ▸
        theme radios the same way the HTML report's palette does: save
        while the app is dark and the PDF comes out in the dark-ink
        variant -- near-black pages, light ink, the app's own palette,
        figures on white plates (the bright-window look of the dark
        HTML report); save while light and it stays the classic white
        paper.  ``auto`` is resolved through ``_resolve_auto_theme``
        first -- a PDF's ink is frozen at write time, so there is no
        reading-time toggle to defer to.  Flip the View ▸ theme radio
        before saving to pick the other variant.

        (100x-132) Both report menus now consult the pre-save picklist
        (:meth:`_session_report_picklist`) -- the desktop twin of the
        web report card's per-section control: every page the walk
        found is offered with a checkbox (all on by default) and only
        the kept pages ship.  Cancel leaves the session untouched.

        (100x-134) The page names CARRY THE COUNT -- the PDF's figure
        pages are named "figure N · <caption>" and its table pages
        "table N · <caption>", numbered in the picklist's own walking
        order, so the page headings in the file read exactly the way
        the picklist's rows did (round 133 numbered the rows; round 134
        makes the file agree).  The "·" separator is latin-1 safe and
        a plain file-name character, so the library's page-name
        validator and the temp-png walk both accept it untouched.

        (100x-135) The title page carries the CONTENTS section -- the
        library's new mini table-of-contents listing every page name
        in the walking order, which means the count prefix now does
        double duty: the picklist's rows, the file's page headings,
        AND the title page's contents list all read the same numbered
        names, so the reader can find any page by the number they
        ticked.  No caller change -- ``save_pdf_report`` grew it.
        """
        live = self._live_session_figures()
        tables = self._live_session_tables()
        if not live and not tables:
            messagebox.showinfo(
                "Nothing to report yet",
                "Run a calculation first -- the report collects every "
                "figure currently on screen (one page each) plus every "
                "filled table (real text pages, one each).",
            )
            return
        if not self._require_pharmaml() or not fpdf_available():
            if self.pharmaml is not None:
                messagebox.showwarning(
                    "Session report needs fpdf",
                    "The multi-page PDF report needs the fpdf package "
                    "(the fpdf2 wheel, extras: reports).\n\n"
                    "    pip install fpdf2\n\n"
                    "Install it, then restart the playground.",
                )
            return
        picked = self._session_report_picklist(live, tables)
        if picked is None:
            return  # the user cancelled the checklist -- no save at all
        live, tables = picked
        path = filedialog.asksaveasfilename(
            title="Save session report",
            defaultextension=".pdf",
            filetypes=[("PDF report", "*.pdf")],
        )
        if not path:
            return

        def unique_name(base: str, *registries: dict[str, Any]) -> str:
            # NB: save_pdf_report validates page names as plain file
            # names -- no directories, no '/' separators.
            name = base
            suffix = 2
            while any(name in registry for registry in registries):
                name = f"{base} ({suffix})"
                suffix += 1
            return name

        figures: dict[str, Any] = {}
        for position, (_host, title, figure) in enumerate(live, start=1):
            # (100x-134) the count prefix -- the picklist's row label,
            # carried into the file's page heading.  unique_name stays
            # as the pathological guard (two identical captions at the
            # same position cannot happen, but the guard is free).
            figures[
                unique_name(f"figure {position} · {title}", figures)
            ] = figure
        import pandas as pd

        table_pages: dict[str, Any] = {}
        for position, (title, headings, rows) in enumerate(tables, start=1):
            frame = pd.DataFrame(rows, columns=headings)
            table_pages[
                unique_name(f"table {position} · {title}", table_pages, figures)
            ] = frame
        stamp = time.strftime("%Y-%m-%d %H:%M")
        # (100x-129) the ink variant rides the theme radios -- captured
        # on the MAIN thread (Tk variables are not safe to read from the
        # worker), auto resolved NOW because a PDF's ink is frozen at
        # write time (no reading-time toggle like the HTML twin's).
        variant = self._theme_var.get()
        if variant == "auto":
            variant = self._resolve_auto_theme()
        # the library's own public contract pins the valid variants
        # (pharmaml.viz.PDF_THEMES) -- guarding here keeps the Tk radios
        # honest even if they ever drift from the library's accepted
        # values, instead of letting save_pdf_report raise mid-job.
        try:
            from pharmaml.viz import PDF_THEMES

            if variant not in PDF_THEMES:
                variant = "light"
        except ImportError:
            if variant not in ("light", "dark"):
                variant = "light"
        variant_label = (
            "dark ink variant (the View ▸ theme radios picked it)"
            if variant == "dark"
            else "classic light paper"
        )

        def work() -> Any:
            from pharmaml.viz import save_pdf_report

            return save_pdf_report(
                figures,
                tables=table_pages or None,
                out_path=path,
                title="PharmaML Playground session",
                subtitle=(
                    f"{len(figures)} figure page(s) · {len(table_pages)} table "
                    f"page(s) · generated {stamp} · playground {__version__} "
                    f"· {variant_label.split(' (')[0]}"
                ),
                close=False,
                theme=variant,
            )

        def render(saved: Any) -> None:
            messagebox.showinfo(
                "Session report saved",
                f"{len(figures)} figure page(s) + {len(table_pages)} table "
                f"page(s) written to\n{saved}\n\nSaved in the {variant_label}. "
                "Flip the View ▸ theme radio before saving to get the "
                "other one.",
            )

        self._start_job("session report", work, render)

    def _menu_save_session_report_html(self) -> None:
        """File ▸ Save session report (HTML)… -- the portable twin.

        (100x-124) :class:`pharmaml.viz.HTMLReport` is the library's
        self-contained HTML report builder -- figures base64-embedded,
        zero external resources, so the file renders identically
        offline and survives being moved or e-mailed -- and until this
        round it had NO caller anywhere.  This is its surface: the
        exact same two axes the PDF report walks (every live session
        figure + every filled table), plus the builder's own metric
        cards (``add_metrics`` -- the session census, which not even
        the library exercised) and an ``add_text`` provenance block.
        No fpdf dependency: one .html file, any browser.

        (100x-126) The report OPENS in the app's own theme -- the View
        ▸ theme radios (auto / light / dark) now do double duty: they
        tint the playground AND bake the report's initial
        ``data-theme``.  A small toggle button rides the top-right of
        every report: one click cycles auto → light → dark at reading
        time, remembered per browser (localStorage) -- the sender pins
        a starting palette, the reader overrides it for themselves,
        and neither touches the other's preference.

        (100x-132) Same picklist as the PDF twin: the pre-save
        checklist runs after the guards, and only the kept pages walk
        into the HTML.  Cancel leaves the session untouched.

        (100x-134) The captions CARRY THE COUNT, exactly like the PDF
        twin's page names: figures ride as "figure N · <caption>" and
        tables as "table N · <caption>", numbered in the picklist's
        own walking order -- both twins' headings now read the way the
        picklist's numbered rows did (the 100x-124 " (2)" caption
        dedupe retired: the position prefix already separates two
        same-titled pages, and reads truer to the checklist).

        (100x-136) The header carries the CONTENTS block -- the SAME
        mini table-of-contents the PDF twin's title page gained in
        100x-135: every table and figure page name in the walking
        order the file writes them (tables first, then figures, the
        picklist's own order), each line the SAME string the page's
        own heading prints.  No caller change -- ``HTMLReport`` grew
        it, so this twin and the library's every other HTML report
        (``save_visual_bundle``'s report.html included) navigate by
        the number the checklist ticked.

        (100x-137) Every Contents line is a CLICKABLE anchor: each
        page rides an id-carrying wrapper (``<section class='page'>``
        for tables, ``<figure class='page'>`` for figures) and the
        line links to it, so a reader jumps straight to the page --
        the jumped-to page flashes an accent ring.  The PDF twin's
        ink is frozen at write time; its Contents lines stay plain
        text.  Again no caller change -- the builder grew it.
        """
        live = self._live_session_figures()
        tables = self._live_session_tables()
        if not live and not tables:
            messagebox.showinfo(
                "Nothing to report yet",
                "Run a calculation first -- the report collects every "
                "figure currently on screen plus every filled table, as "
                "one self-contained HTML file (figures embedded, no "
                "external resources).",
            )
            return
        if not self._require_pharmaml():
            return
        picked = self._session_report_picklist(live, tables)
        if picked is None:
            return  # the user cancelled the checklist -- no save at all
        live, tables = picked
        path = filedialog.asksaveasfilename(
            title="Save session report (HTML)",
            defaultextension=".html",
            filetypes=[("HTML report", "*.html"), ("All files", "*.*")],
        )
        if not path:
            return
        stamp = time.strftime("%Y-%m-%d %H:%M")
        # captured on the MAIN thread (Tk variables are not safe to read
        # from the worker); the app's theme radios pin the report's
        # initial palette -- auto follows the READER's OS, not ours.
        theme = self._theme_var.get()
        # (100x-127) the library's own public contract pins the valid
        # themes (pharmaml.viz.REPORT_THEMES) -- guarding here keeps the
        # Tk radios honest even if they ever drift from the library's
        # accepted values, instead of letting HTMLReport raise mid-job.
        try:
            from pharmaml.viz import REPORT_THEMES

            if theme not in REPORT_THEMES:
                theme = "auto"
        except ImportError:
            pass  # the worker's HTMLReport import reports this honestly
        try:
            cards = len(self._live_cards())
        except Exception:  # noqa: BLE001 - the census is cosmetic
            cards = 0
        figure_count = len(live)
        table_count = len(tables)
        # (100x-134) the count-prefix walk -- the picklist's numbered
        # rows, carried into the HTML's captions/headings: "figure N ·
        # <caption>" / "table N · <caption>" in the dialog's order.
        # The position prefix separates same-titled pages on its own
        # (the old " (2)" caption dedupe retired with it).
        captioned = [
            (f"figure {position} · {title}", figure)
            for position, (_host, title, figure) in enumerate(live, start=1)
        ]
        table_headings = [
            f"table {position} · {title}"
            for position, (title, _headings, _rows) in enumerate(tables, start=1)
        ]

        def work() -> Any:
            import pandas as pd

            from pharmaml.viz import HTMLReport

            report = HTMLReport(
                "PharmaML Playground session",
                subtitle=(
                    f"{figure_count} figure(s) · {table_count} table(s) · "
                    f"generated {stamp} · playground {__version__}"
                ),
                theme=theme,
            )
            report.add_metrics(
                {
                    "figures": str(figure_count),
                    "tables": str(table_count),
                    "cards on screen": str(cards),
                    "pharmaml": str(self.pharmaml.__version__),
                }
            )
            report.add_text(
                "Every figure and every filled table currently on screen, "
                "collected in one pass.  A figure replaced on its card is "
                "gone -- the report shows the newest render, the honest "
                "provenance of the session.  The figures are embedded as "
                "base64, so this file needs no network and no companion "
                "assets: move it, mail it, archive it.",
                heading="What this file contains",
            )
            for heading, (title, headings, rows) in zip(table_headings, tables):
                report.add_table(
                    pd.DataFrame(rows, columns=headings), heading=heading
                )
            for caption, figure in captioned:
                report.add_figure(figure, caption=caption)
            return report.save(path)

        def render(saved: Any) -> None:
            messagebox.showinfo(
                "Session report saved",
                f"{figure_count} figure(s) + {table_count} table(s) written to\n"
                f"{saved}\n\nSelf-contained HTML -- the figures are embedded, "
                "so the file renders identically offline and survives "
                "being moved or e-mailed.\n\n"
                "The header's Contents block lists every page by its "
                "number -- the same numbers the checklist's rows read.\n\n"
                f"Theme: opens {theme} (the app's setting); the button in "
                "the report's top-right corner cycles it per reader.",
            )

        self._start_job("session report (HTML)", work, render)

    def _show_about(self) -> None:
        pharmaml_line = (
            f"pharmaml {self.pharmaml.__version__}"
            if self.pharmaml is not None
            else "pharmaml: NOT LOADED (run from the toolkit root)"
        )
        messagebox.showinfo(
            "About PharmaML Playground",
            f"PharmaML Playground {__version__}\n{pharmaml_line}\n\n"
            "A single-file graphical front end for the pharmaml toolkit:\n"
            "chemistry · PK/PD · cell lines · docking · QSAR machine learning · "
            "deep learning · generative design.\n\n"
            "Calculations run in pharmaml itself -- the playground only\n"
            "collects your inputs and renders the results.",
        )

    def _show_dependency_report(self) -> None:
        lines = [f"{'module':<14} status", "-" * 28]
        for module, label, _purpose, _pip in _DEPENDENCIES:
            lines.append(f"{label:<14} {'installed' if self.deps.get(module) else 'missing'}")
        lines.append(f"{'tkinter':<14} {'installed' if tk is not None else 'missing'}")
        report = "\n".join(lines)
        print(report)
        messagebox.showinfo("Dependency report", report)

