    def _bio_open_csv(self) -> None:
        if not self._require_pharmaml() or not self._require("pandas", "screen loading"):
            return
        path = filedialog.askopenfilename(
            title="Open a response screen",
            filetypes=[("Data files", "*.csv *.tsv *.txt"), ("All files", "*.*")],
        )
        if path:
            # (100x-143) the dialog flow is job-based -- a big screen
            # (audit + replicate collapse included) never freezes the
            # window; the tiny bundled example stays sync.
            self._bio_load_file(Path(path))

    def _bio_load_example(self) -> None:
        if not self._require_pharmaml() or not self._require("pandas", "screen loading"):
            return
        path = EXAMPLES_DIR / "cellline_screen.csv"
        if not path.is_file():
            messagebox.showwarning(
                "Missing example", "examples/data/cellline_screen.csv was not found."
            )
            return
        self._bio_load_path(path)

    def _bio_load_path(self, path: Path) -> None:
        """Synchronous load + audit + adopt (examples, tests, relays).

        (100x-143) The file-dialog flow now rides :meth:`_bio_load_file`
        (a worker-thread job); this synchronous core stays for the tiny
        bundled example and for callers that need the screen RIGHT NOW.
        """
        try:
            from pharmaml.biology import (
                audit_response_table,
                collapse_replicates,
                load_response_table,
            )

            raw = load_response_table(path)
            audit_frame = audit_response_table(raw)
            screen = raw
            if bool(self._bio_collapse_var.get()):
                screen = collapse_replicates(raw)
        except Exception as exc:  # noqa: BLE001
            self._show_error("Could not read the response screen", exc)
            return
        self._bio_adopt_screen(raw, audit_frame, screen, path)

    def _bio_load_file(self, path: Path) -> None:
        """(100x-143) Job-based load + audit + adopt -- the dialog flow.

        A big screen used to freeze the window (``load_response_table``
        + ``audit_response_table`` + ``collapse_replicates`` all ran on
        the main thread -- the audit's §4 finding, this tab's own twin
        of the loader port).  The read/audit/collapse pipeline now
        rides the worker pool; the collapse checkbox is captured on the
        MAIN thread (a Tk variable must never be read from a worker)
        and the adoption reuses the shared :meth:`_bio_adopt_screen`,
        so the sync and async loaders can never drift apart.
        """
        collapse = bool(self._bio_collapse_var.get())

        def work(report: Any) -> Any:
            from pharmaml.biology import (
                audit_response_table,
                collapse_replicates,
                load_response_table,
            )

            # (100x-144) the reporter rides straight through the loader
            # -- a big screen's read streams chunk-by-chunk; (100x-146)
            # the AUDIT/COLLAPSE phases now speak too: a counter-style
            # note after the read ("auditing rows...", "collapsing
            # replicates") so a slow in-memory pass is never a silent
            # frozen bar on a huge screen
            raw = load_response_table(path, report=report)
            rows = len(raw.frame)
            report(rows, None, "auditing rows")
            audit_frame = audit_response_table(raw)
            if collapse:
                report(rows, None, "collapsing replicates")
                screen = collapse_replicates(raw)
            else:
                screen = raw
            return raw, audit_frame, screen

        def render(payload: tuple[Any, Any, Any]) -> None:
            raw, audit_frame, screen = payload
            self._bio_adopt_screen(raw, audit_frame, screen, path)

        self._start_job(f"loading {path.name}", work, render)

    def _bio_adopt_screen(self, raw: Any, audit_frame: Any, screen: Any, path: Path) -> None:
        """Adopt a parsed screen (audit text, combos, info label).

        (100x-143) Extracted from ``_bio_load_path`` so the sync loader
        and the job-based file loader share ONE adoption body.
        """
        self._bio_screen = screen
        self._bio_screen_path = path
        self._bio_collapsed = screen is not raw
        self._bio_matrix = None
        self._bio_matrix_metric = None

        # the audit always describes the ORIGINAL table, so replicate
        # issues stay visible even when they were just collapsed away
        self._bio_audit_text.delete("1.0", "end")
        if len(audit_frame):
            self._bio_audit_text.insert("1.0", audit_frame.to_string())
        else:
            self._bio_audit_text.insert(
                "1.0", "audit: no issues — identifiers, metric values and pairs all clean"
            )

        raw_rows = len(raw.frame)
        rows_note = f"{raw_rows:,} rows"
        if len(screen.frame) != raw_rows:
            rows_note += f" ({len(screen.frame):,} after collapsing replicates)"
        metrics = ", ".join(screen.metrics)
        self._bio_info.configure(
            text=(
                f"{path.name} — {rows_note} · {len(screen.cell_lines)} cell lines · "
                f"{len(screen.compounds)} compounds · metric(s): {metrics}"
            )
        )
        self._bio_metric_combo["values"] = list(screen.metrics)
        if screen.metrics:
            self._bio_metric_combo.set(screen.metrics[0])
        compounds = list(screen.compounds)
        self._bio_compound_combo["values"] = compounds
        self._bio_marker_compound_combo["values"] = compounds
        if compounds:
            self._bio_compound_var.set(compounds[0])

    def _bio_replicate_variability(self) -> None:
        """Replicate spread per duplicated pair (biology.replicate_variability)."""
        if not self._require_pharmaml() or not self._require("pandas", "the audit"):
            return
        if self._bio_screen is None:
            messagebox.showwarning("No screen", "Load a response screen first.")
            return
        path = getattr(self, "_bio_screen_path", None)

        def work() -> Any:
            from pharmaml.biology import load_response_table, replicate_variability

            # replicates must be audited BEFORE any collapsing -- reload
            # the raw table (the loaded screen may already be collapsed)
            raw = load_response_table(path) if path is not None else self._bio_screen
            return replicate_variability(raw)

        def render(frame: Any) -> None:
            self._bio_audit_text.delete("1.0", "end")
            if frame is None or not len(frame):
                self._bio_audit_text.insert(
                    "1.0",
                    "replicate variability: no duplicated cell-line × "
                    "compound pairs in this screen — nothing to compare",
                )
                return
            self._bio_audit_text.insert(
                "1.0",
                "replicate variability (per duplicated pair, "
                "before any collapsing):\n\n" + frame.to_string(index=False),
            )

        self._start_job("replicate variability", work, render)

    def _bio_summarize_compounds(self) -> None:
        """Per-compound statistics over the chosen metric (summarize_compounds)."""
        if not self._require_pharmaml() or not self._require("pandas", "the summary"):
            return
        if self._bio_screen is None:
            messagebox.showwarning("No screen", "Load a response screen first.")
            return
        metric = self._bio_metric_combo.get()
        if not metric:
            messagebox.showwarning("No metric", "Pick the response metric.")
            return
        lower_is_sensitive = bool(self._bio_lower_var.get())

        def work() -> Any:
            from pharmaml.biology import summarize_compounds

            return summarize_compounds(
                self._bio_screen, metric, higher_is_more_sensitive=not lower_is_sensitive
            )

        def render(frame: Any) -> None:
            self._bio_audit_text.delete("1.0", "end")
            header = (
                f"compound summary — {metric} "
                f"({'lower = more sensitive' if lower_is_sensitive else 'higher = more sensitive'}):\n\n"
            )
            self._bio_audit_text.insert("1.0", header + frame.to_string(index=False))

        self._start_job(f"compound summary ({metric})", work, render)

    def _bio_build_matrix(self) -> None:
        if not self._require_pharmaml() or not self._require("pandas", "the matrix"):
            return
        if self._bio_screen is None:
            messagebox.showwarning("No screen", "Load a response screen first.")
            return
        metric = self._bio_metric_combo.get()
        if not metric:
            messagebox.showwarning("No metric", "Pick the response metric.")
            return

        def work() -> Any:
            from pharmaml.biology import response_matrix

            return response_matrix(self._bio_screen, metric), metric

        def render(payload: Any) -> None:
            matrix, used_metric = payload
            self._bio_render_matrix(matrix, used_metric)

        self._start_job(f"sensitivity matrix ({metric})", work, render)

    def _bio_render_matrix(self, matrix: Any, metric: str) -> None:
        self._bio_matrix = matrix
        self._bio_matrix_metric = metric
        tree = self._bio_matrix_tree
        tree.delete(*tree.get_children())
        compounds = [str(column) for column in matrix.columns]
        tree["columns"] = compounds
        for column in compounds:
            tree.heading(column, text=column)
            tree.column(column, width=96, minwidth=72, stretch=True)
        for cell_line, row in matrix.iterrows():
            values = [
                "" if isinstance(value, float) and math.isnan(value) else _cell_text(value)
                for value in row.tolist()
            ]
            tree.insert("", "end", text=str(cell_line), values=values)
        self._bio_matrix_info.configure(
            text=(
                f"{len(matrix.index)} cell lines × {len(matrix.columns)} compounds · "
                f"untested pairs blank · metric {metric}"
            )
        )

    def _bio_call_sensitive(self) -> None:
        if not self._require_pharmaml() or not self._require("pandas", "sensitivity calls"):
            return
        if self._bio_screen is None:
            messagebox.showwarning("No screen", "Load a response screen first.")
            return
        compound = self._bio_compound_var.get()
        if not compound:
            messagebox.showwarning("No compound", "Pick the compound to call.")
            return
        try:
            sensitive_q = parse_float(
                self._bio_q1.get(), "sensitive quantile", minimum=0.0, maximum=1.0
            )
            resistant_q = parse_float(
                self._bio_q2.get(), "resistant quantile", minimum=0.0, maximum=1.0
            )
            if sensitive_q >= resistant_q:
                raise ValueError("the sensitive quantile must be below the resistant quantile")
        except ValueError as exc:
            messagebox.showerror("Input", str(exc))
            return
        lower = bool(self._bio_lower_var.get())
        metric = self._bio_metric_combo.get()

        def work() -> Any:
            from pharmaml.biology import call_sensitive_resistant, response_matrix

            matrix = self._bio_matrix
            built = matrix is None or self._bio_matrix_metric != metric
            if built:
                matrix = response_matrix(self._bio_screen, metric)
            calls = call_sensitive_resistant(
                matrix[compound], sensitive_q, resistant_q, lower_is_sensitive=lower
            )
            return matrix, metric, built, calls, compound

        def render(payload: Any) -> None:
            matrix, used_metric, built, calls, used_compound = payload
            if built:
                self._bio_render_matrix(matrix, used_metric)
            counts = calls.value_counts()
            labels = ("sensitive", "intermediate", "resistant", "not tested")
            summary = " · ".join(f"{int(counts.get(label, 0))} {label}" for label in labels)
            self._bio_calls_summary.configure(
                text=f"{used_compound}: {summary}", style="Field.TLabel"
            )
            self._bio_calls_tree.delete(*self._bio_calls_tree.get_children())
            rank = {label: index for index, label in enumerate(labels)}
            for cell_line, call in sorted(
                calls.items(), key=lambda item: (rank.get(item[1], 99), str(item[0]))
            ):
                self._bio_calls_tree.insert("", "end", text=str(cell_line), values=(call,))

        self._start_job(f"sensitivity calls ({compound})", work, render)

    def _bio_ln_to_pic50(self) -> None:
        self._bio_convert_ic50("ln")

    def _bio_pic50_to_ln(self) -> None:
        self._bio_convert_ic50("pic50")

    def _bio_convert_ic50(self, direction: str) -> None:
        if not self._require_pharmaml() or not self._require("numpy", "conversion"):
            return
        from pharmaml.biology import ln_ic50_to_pic50, pic50_to_ln_ic50

        try:
            value = parse_float(self._bio_ic50_entry.get(), "value")
            result = ln_ic50_to_pic50(value) if direction == "ln" else pic50_to_ln_ic50(value)
        except Exception as exc:  # noqa: BLE001
            self._show_error("Conversion failed", exc)
            return
        self._bio_ic50_result.configure(text=f"{result:.4f}")

    def _bio_open_expr_csv(self) -> None:
        if not self._require_pharmaml() or not self._require("pandas", "expression loading"):
            return
        path = filedialog.askopenfilename(
            title="Open an expression table",
            filetypes=[("CSV table", "*.csv"), ("All files", "*.*")],
        )
        if path:
            # (100x-143) the dialog flow is job-based -- a wide
            # expression matrix never freezes the window.
            self._bio_load_expr_file(Path(path))

    def _bio_load_expr_example(self) -> None:
        if not self._require_pharmaml() or not self._require("pandas", "expression loading"):
            return
        path = EXAMPLES_DIR / "cellline_expression.csv"
        if not path.is_file():
            messagebox.showwarning(
                "Missing example", "examples/data/cellline_expression.csv was not found."
            )
            return
        self._bio_load_expr_path(path)

    def _bio_load_expr_path(self, path: Path) -> None:
        """Synchronous read + adopt (examples, tests, relays)."""
        try:
            import pandas as pd

            try:
                frame = pd.read_csv(path, index_col="cell_line")
            except ValueError:
                # user tables name their identifier column differently --
                # fall back to the first column as the cell-line index
                frame = pd.read_csv(path, index_col=0)
        except Exception as exc:  # noqa: BLE001
            self._show_error("Could not read the expression table", exc)
            return
        self._bio_adopt_expr_frame(frame, path)

    def _bio_load_expr_file(self, path: Path) -> None:
        """(100x-143) Job-based read + adopt -- the file-dialog flow.

        A wide expression matrix used to freeze the window
        (``pd.read_csv`` ran on the main thread, twice -- the indexed
        read plus the fallback); the read now rides the worker pool,
        the status bar carries ``loading {name}``, and the adoption
        reuses the shared :meth:`_bio_adopt_expr_frame`.
        (100x-146) The read itself streams through
        ``read_indexed_table_with_progress`` -- the indexed twin of the
        round-144 reader: a large matrix carries a determinate
        rows/ETA bar instead of the open-ended marquee (the
        ``cell_line`` label index with its positional fallback kept
        byte-for-byte; small files keep the plain pair), and a ragged
        row landing on a chunk boundary is rejected up front rather
        than silently truncated by pandas' own chunked parser.
        """

        def work(report: Any) -> Any:
            from pharmaml.utils.io import read_indexed_table_with_progress

            return read_indexed_table_with_progress(path, report, index_col="cell_line")

        def render(frame: Any) -> None:
            self._bio_adopt_expr_frame(frame, path)

        self._start_job(f"loading {path.name}", work, render)

    def _bio_adopt_expr_frame(self, frame: Any, path: Path) -> None:
        """Adopt a parsed expression matrix (info label + state reset).

        (100x-143) Extracted from ``_bio_load_expr_path`` so the sync
        loader and the job-based file loader share ONE adoption body.
        """
        if frame.empty:
            messagebox.showwarning("Empty table", f"{path.name} has no rows.")
            return
        self._bio_expr = frame
        self._bio_expr_norm = None
        self._bio_expr_info.configure(
            text=f"{path.name} — {len(frame):,} cell lines × {len(frame.columns):,} genes"
        )

    def _bio_rank_variable_genes(self) -> None:
        """The MAD variability ranking of the loaded table (100x-120).

        ``most_variable_genes`` finally has its GUI surface: the N
        genes with the highest median absolute deviation across the
        panel, listed most-variable-first with their MAD values --
        the classic pre-filter question ("which probes carry signal
        at all?") answerable without loading a screen.
        """
        if not self._require_pharmaml() or not self._require("pandas", "the MAD ranking"):
            return
        frame = getattr(self, "_bio_expr", None)
        if frame is None:
            messagebox.showwarning(
                "No expression table", "Open an expression CSV (or load the example) first."
            )
            return
        try:
            top_n = parse_int(self._bio_mad_n.get(), "top N genes", minimum=1, maximum=100000)
        except ValueError as exc:
            messagebox.showerror("Input", str(exc))
            return
        n_genes = len(frame.columns)

        def work() -> Any:
            import pandas as pd

            from pharmaml.biology import most_variable_genes

            genes = most_variable_genes(frame, n=top_n)
            # MAD per kept gene, ranked -- recompute honestly from the
            # frame (the library returns names only)
            mads = (frame[genes] - frame[genes].median()).abs().median()
            ranked = pd.DataFrame({"gene": genes}).set_index("gene")
            ranked["MAD"] = mads
            return ranked

        def render(ranked: Any) -> None:
            self._bio_mad_text.delete("1.0", "end")
            self._bio_mad_text.insert("1.0", ranked.to_string())
            self._bio_mad_summary.configure(
                text=(
                    f"top {len(ranked)} of {n_genes:,} genes by MAD — "
                    f"most variable: {ranked.index[0]}"
                ),
                style="Field.TLabel",
            )

        self._start_job("MAD gene ranking", work, render)

    def _bio_discover_biomarkers(self) -> None:
        if not self._require_pharmaml():
            return
        for module in ("numpy", "pandas", "scipy"):
            if not self._require(module, "biomarker discovery"):
                return
        if self._bio_screen is None or self._bio_expr is None:
            messagebox.showwarning(
                "Missing data",
                "Biomarker discovery needs BOTH a response screen and an "
                "expression table — load one of each above, then try again.",
            )
            return
        compound = self._bio_compound_var.get()
        if not compound:
            messagebox.showwarning("No compound", "Pick the compound to analyse.")
            return
        method = self._bio_method_combo.get() or "spearman"
        try:
            top_n = parse_int(self._bio_topn_entry.get(), "top N genes", minimum=1, maximum=500)
        except ValueError as exc:
            messagebox.showerror("Input", str(exc))
            return
        lower = bool(self._bio_marker_lower_var.get())
        metric = self._bio_metric_combo.get()

        def work() -> Any:
            from pharmaml.biology import (
                impute_expression,
                normalize_expression,
                response_matrix,
                sensitivity_associations,
                top_biomarkers,
            )

            norm = self._bio_expr_norm
            if norm is None:
                norm = impute_expression(normalize_expression(self._bio_expr))
            matrix = self._bio_matrix
            built = matrix is None or self._bio_matrix_metric != metric
            if built:
                matrix = response_matrix(self._bio_screen, metric)
            associations = sensitivity_associations(norm, matrix[compound], method=method)
            top = top_biomarkers(associations, n=top_n)
            return top, associations, norm, matrix, metric, built, compound

        def render(payload: Any) -> None:
            from pharmaml.biology import direction_of_association

            top, associations, norm, matrix, used_metric, built, used_compound = payload
            self._bio_expr_norm = norm
            if built:
                self._bio_render_matrix(matrix, used_metric)
            n_significant = int(associations["significant"].sum())
            strongest = float(associations["rho"].abs().max())
            self._bio_marker_summary.configure(
                text=(
                    f"{len(associations):,} genes correlated · "
                    f"{n_significant} significant at FDR < 0.05 · "
                    f"strongest |rho| {strongest:.3f} — {used_compound}"
                ),
                style="Field.TLabel",
            )
            self._bio_marker_tree.delete(*self._bio_marker_tree.get_children())
            for _, row in top.iterrows():
                try:
                    rho = float(row["rho"])
                except (TypeError, ValueError):
                    rho = float("nan")
                self._bio_marker_tree.insert(
                    "",
                    "end",
                    values=(
                        _cell_text(row["gene"], limit=18),
                        format_number(rho),
                        _cell_text(row["p_value"]),
                        _cell_text(row["fdr"]),
                        "Yes" if bool(row["significant"]) else "No",
                        direction_of_association(rho, lower_is_sensitive=lower),
                    ),
                )

        self._start_job(f"biomarkers for {compound}", work, render)

    # ------------------------------------------------------------------ #
    # Docking tab
    # ------------------------------------------------------------------ #
    def _build_docking_tab(self) -> None:
        page = self._new_page("Docking")

        # -- card 1: ligand library -> PDBQT campaign -------------------- #
        ligands = make_card(
            page.grid,
            "Ligand library → PDBQT",
            row=0,
            column=0,
            subtitle="A SMILES CSV becomes one folder per ligand, each with a "
            "3D l.pdbqt (Meeko + RDKit).",
        )
        lib_buttons = ttk.Frame(ligands, style="Card.TFrame")
        lib_buttons.grid(row=0, column=0, columnspan=2, sticky="w")
        lib_open_btn = self._action_button(lib_buttons, "Open CSV…", self._dock_open_csv)
        lib_open_btn.pack(side="left")
        lib_example_btn = self._action_button(
            lib_buttons,
            "Load example",
            self._dock_load_example,
            tooltip="The bundled 10-row library (8 valid SMILES, 2 broken "
            "rows on purpose) -- examples/data/ligand_library.csv.",
        )
        lib_example_btn.pack(side="left", padx=(10, 0))
        self._dock_lib_info = ttk.Label(ligands, text="no library loaded", style="CardMuted.TLabel")
        self._dock_lib_info.grid(row=1, column=0, columnspan=2, sticky="w", pady=(6, 0))
        out_buttons = ttk.Frame(ligands, style="Card.TFrame")
        out_buttons.grid(row=2, column=0, columnspan=2, sticky="w")
        out_btn = self._action_button(
            out_buttons, "Choose output folder…", self._dock_choose_out_dir
        )
        out_btn.pack(side="left")
        self._dock_out_info = ttk.Label(
            out_buttons,
            text="no output folder chosen",
            style="CardMuted.TLabel",
            wraplength=280,
            justify="left",
        )
        self._dock_out_info.pack(side="left", padx=(10, 0))
        prep_btn = self._action_button(
            ligands,
            "Prepare ligands",
            self._dock_prepare_ligands,
            primary=True,
            tooltip="Embeds and atom-types every valid SMILES in a worker "
            "thread; one sub-folder per ligand under the output root.",
        )
        prep_btn.grid(row=ligands.grid_size()[1], column=0, sticky="w", pady=(6, 0))
        self._dock_prep_summary = ttk.Label(
            ligands,
            text="—",
            style="CardMuted.TLabel",
            wraplength=300,
            justify="left",
        )
        self._dock_prep_summary.grid(
            row=prep_btn.grid_info()["row"], column=1, sticky="w", padx=(10, 0)
        )
        lib_tree_frame = ttk.Frame(ligands, style="Card.TFrame")
        grid_append(ligands, lib_tree_frame, sticky="nsew", weight=True)
        self._dock_lib_tree = ttk.Treeview(
            lib_tree_frame,
            columns=("folder", "name", "ok", "atoms", "torsdof", "error"),
            show="headings",
            height=8,
        )
        for column, width in (
            ("folder", 120),
            ("name", 100),
            ("ok", 44),
            ("atoms", 60),
            ("torsdof", 66),
            ("error", 170),
        ):
            self._dock_lib_tree.heading(column, text=column)
            self._dock_lib_tree.column(
                column, width=width, minwidth=44, stretch=(column == "error")
            )
        lib_bar = ttk.Scrollbar(
            lib_tree_frame, orient="vertical", command=self._dock_lib_tree.yview
        )
        self._dock_lib_tree.configure(yscrollcommand=lib_bar.set)
        self._dock_lib_tree.pack(side="left", fill="both", expand=True)
        lib_bar.pack(side="right", fill="y")
        lib_save_btn = self._action_button(
            ligands, "Save report CSV…", self._dock_save_ligand_report
        )
        lib_save_btn.grid(
            row=ligands.grid_size()[1], column=0, columnspan=2, sticky="w", pady=(6, 0)
        )

        # -- card 2: receptor preparation -------------------------------- #
        receptor = make_card(
            page.grid,
            "Receptor preparation",
            row=0,
            column=1,
            subtitle="PDB / CIF / PDBQT → a docking-ready receptor PDBQT "
            "(waters out, atom types in).",
        )
        rec_buttons = ttk.Frame(receptor, style="Card.TFrame")
        rec_buttons.grid(row=0, column=0, columnspan=2, sticky="w")
        rec_open_btn = self._action_button(
            rec_buttons, "Open PDB / CIF / PDBQT…", self._dock_open_receptor
        )
        rec_open_btn.pack(side="left")
        rec_example_btn = self._action_button(
            rec_buttons,
            "Load example",
            self._dock_load_receptor_example,
            tooltip="The bundled hen egg-white lysozyme (examples/data/lysozyme_1aki.pdb).",
        )
        rec_example_btn.pack(side="left", padx=(10, 0))
        self._dock_receptor_info = ttk.Label(
            receptor,
            text="no receptor source selected",
            style="CardMuted.TLabel",
            wraplength=300,
            justify="left",
        )
        self._dock_receptor_info.grid(row=1, column=0, columnspan=2, sticky="w", pady=(6, 0))
        self._dock_remove_waters_var = tk.BooleanVar(value=True)
        waters_check = ttk.Checkbutton(
            receptor, text="remove waters", variable=self._dock_remove_waters_var
        )
        form_row(receptor, "waters", waters_check)
        self._dock_keep_hetatm_var = tk.BooleanVar(value=False)
        hetatm_check = ttk.Checkbutton(
            receptor, text="keep HETATM ligands/ions", variable=self._dock_keep_hetatm_var
        )
        form_row(receptor, "HETATM", hetatm_check)
        self._dock_strip_h_var = tk.BooleanVar(value=True)
        strip_check = ttk.Checkbutton(
            receptor, text="strip hydrogens", variable=self._dock_strip_h_var
        )
        form_row(receptor, "hydrogens", strip_check)
        self._dock_bad_res_var = tk.BooleanVar(value=True)
        bad_res_check = ttk.Checkbutton(
            receptor, text="auto-remove bad residues", variable=self._dock_bad_res_var
        )
