    def _ml_plot_learning_curve(self) -> None:
        """Train-set size vs CV score for the last trained model (100x-120).

        ``plot_learning_curve`` gains its GUI surface: the last run's
        train+test rows are reassembled (the held-out rows are the most
        honest extra points the curve can have) and refit at growing
        train sizes -- the "should we assay more compounds?" figure.
        """
        run = getattr(self, "_ml_last_run", None)
        if run is None:
            messagebox.showinfo(
                "No trained model",
                "Train a model first -- the learning curve needs the last run's data.",
            )
            return
        trained, _report, _task, x_train, y_train, x_test, y_test, target = run
        if not self._require_pharmaml() or not self._require("matplotlib", "the learning curve"):
            return
        if not self._require("sklearn", "the learning curve"):
            return
        try:
            folds = parse_int(self._curve_cv.get(), "CV folds", minimum=2, maximum=10)
        except ValueError as exc:
            messagebox.showerror("Input", str(exc))
            return
        model_name = trained.name

        def work() -> Any:
            import numpy as np
            import pandas as pd

            from pharmaml.viz import plot_learning_curve

            if isinstance(x_train, pd.DataFrame):
                full_x = pd.concat([x_train, x_test], ignore_index=True)
                full_y = pd.concat([pd.Series(y_train), pd.Series(y_test)], ignore_index=True)
            else:
                full_x = np.concatenate([np.asarray(x_train), np.asarray(x_test)], axis=0)
                full_y = np.concatenate([np.asarray(y_train), np.asarray(y_test)], axis=0)
            return plot_learning_curve(
                trained.model,
                full_x,
                full_y,
                cv=folds,
                title=f"Learning curve — {model_name} ({target})",
            )

        def render(figure: Any) -> None:
            self._render_figure(self._ml_host, figure)
            self._ml_result_note.configure(
                text="learning curve replaces the parity figure — Train & evaluate brings it back"
            )

        self._start_job("learning curve", work, render)

    def _ml_plot_permutation(self) -> None:
        """Permutation importance of the last trained model (100x-145).

        D2.py's own interpretability step as a Results-card button:
        every feature column is shuffled on the held-out rows and the
        score drop (with its ±1 std whisker) is drawn top-first --
        the noise features a shuffle HELPED render in red.
        (100x-146) The table itself rides the render as
        ``_ml_perm_frame`` -- the card's Save-CSV twin writes it
        (feature, importance_mean, importance_std) while the figure
        export keeps the picture.
        """
        run = getattr(self, "_ml_last_run", None)
        if run is None:
            messagebox.showinfo(
                "No trained model",
                "Train a model first -- the permutation importance needs "
                "the last run's held-out rows.",
            )
            return
        trained, _report, task, _x_train, _y_train, x_test, y_test, target = run
        if not self._require_pharmaml() or not self._require("matplotlib", "the figure"):
            return
        if not self._require("sklearn", "the permutation importance"):
            return
        try:
            repeats = parse_int(self._perm_repeats.get(), "repeats", minimum=1, maximum=50)
        except ValueError as exc:
            messagebox.showerror("Input", str(exc))
            return
        model_name = trained.name

        def work() -> Any:
            from pharmaml.ml import permutation_feature_importance
            from pharmaml.viz import plot_permutation_importance

            importance = permutation_feature_importance(
                trained.model,
                x_test,
                y_test,
                task=task,
                n_repeats=repeats,
            )
            figure = plot_permutation_importance(
                importance,
                title=f"Permutation importance — {model_name} ({target})",
            )
            return importance, figure

        def render(payload: tuple[Any, Any]) -> None:
            importance, figure = payload
            self._render_figure(self._ml_host, figure)
            self._ml_perm_frame = importance.as_frame()
            self._ml_result_note.configure(
                text="permutation importance replaces the parity figure — Train & evaluate brings it back"
            )

        self._start_job("permutation importance", work, render)

    def _ml_perm_save(self) -> None:
        """(100x-146) Save the last permutation-importance table as CSV.

        The figure export keeps the picture; this twin keeps the
        NUMBERS (feature, importance_mean, importance_std -- the spread
        the whiskers drew) in the audit card's own save-dialog shape.
        Retires with the run: a new train clears it.
        """
